 1→import { InstrumentId } from '../patterns/types';
 2→
 3→export const TIMING_THRESHOLDS = {
 4→  PERFECT: 0.015,
 5→  GREAT: 0.030,
 6→  GOOD: 0.050,
 7→  MAX_WINDOW: 0.100,
 8→} as const;
 9→
10→export type TimingGrade = 'perfect' | 'great' | 'good' | 'early' | 'late' | 'miss';
11→
12→export type LiveMode = 'full-kit' | 'single-track';
13→
14→export interface ExpectedBeat {
15→  step: number;
16→  time: number;
17→  instrumentId: InstrumentId;
18→  matched: boolean;
19→}
20→
21→export interface TapEvent {
22→  timestamp: number;
23→  instrumentId: InstrumentId;
24→  matchedStep: number | null;
25→  offset: number;
26→  grade: TimingGrade;
27→}
28→
29→export interface StepAccuracy {
30→  step: number;
31→  instrumentId: InstrumentId;
32→  grade: TimingGrade;
33→  offset: number;
34→}
35→
36→export interface BarAccuracy {
37→  accuracy: number;
38→  hits: number;
39→  total: number;
40→}
41→
42→export interface SessionStats {
43→  totalExpected: number;
44→  totalHits: number;
45→  totalMisses: number;
46→  perfectCount: number;
47→  greatCount: number;
48→  goodCount: number;
49→  earlyLateCount: number;
50→  averageOffset: number;
51→  currentStreak: number;
52→  bestStreak: number;
53→  barHistory: BarAccuracy[];
54→}
55→
56→export interface KeyMapping {
57→  key: string;
58→  instrumentId: InstrumentId;
59→  label: string;
60→}
61→
62→export const DEFAULT_KEY_MAPPINGS: KeyMapping[] = [
63→  { key: 'KeyD', instrumentId: 'kick', label: 'D' },
64→  { key: 'KeyF', instrumentId: 'snare', label: 'F' },
65→  { key: 'KeyJ', instrumentId: 'hihat-closed', label: 'J' },
66→  { key: 'KeyK', instrumentId: 'hihat-open', label: 'K' },
67→  { key: 'KeyS', instrumentId: 'tom-high', label: 'S' },
68→  { key: 'KeyA', instrumentId: 'tom-mid', label: 'A' },
69→  { key: 'KeyL', instrumentId: 'tom-low', label: 'L' },
70→  { key: 'KeyG', instrumentId: 'crash', label: 'G' },
71→  { key: 'KeyH', instrumentId: 'ride', label: 'H' },
72→];
