 1→import { InstrumentId } from '../patterns/types';
 2→import {
 3→  ExpectedBeat,
 4→  TapEvent,
 5→  TimingGrade,
 6→  TIMING_THRESHOLDS,
 7→} from './types';
 8→
 9→export class TapMatcher {
10→  private expectedBeats: ExpectedBeat[] = [];
11→  private taps: TapEvent[] = [];
12→
13→  reset(): void {
14→    this.expectedBeats = [];
15→    this.taps = [];
16→  }
17→
18→  addExpectedBeat(step: number, time: number, instrumentId: InstrumentId): void {
19→    this.expectedBeats.push({ step, time, instrumentId, matched: false });
20→  }
21→
22→  processTap(tapTime: number, instrumentId: InstrumentId): TapEvent {
23→    let bestBeat: ExpectedBeat | null = null;
24→    let bestAbsOffset = Infinity;
25→
26→    for (const beat of this.expectedBeats) {
27→      if (beat.matched || beat.instrumentId !== instrumentId) continue;
28→      const absOffset = Math.abs(tapTime - beat.time);
29→      if (absOffset < bestAbsOffset) {
30→        bestAbsOffset = absOffset;
31→        bestBeat = beat;
32→      }
33→    }
34→
35→    let grade: TimingGrade;
36→    let matchedStep: number | null = null;
37→    let offset = 0;
38→
39→    if (bestBeat && bestAbsOffset <= TIMING_THRESHOLDS.MAX_WINDOW) {
40→      bestBeat.matched = true;
41→      matchedStep = bestBeat.step;
42→      offset = tapTime - bestBeat.time;
43→
44→      if (bestAbsOffset <= TIMING_THRESHOLDS.PERFECT) grade = 'perfect';
45→      else if (bestAbsOffset <= TIMING_THRESHOLDS.GREAT) grade = 'great';
46→      else if (bestAbsOffset <= TIMING_THRESHOLDS.GOOD) grade = 'good';
47→      else grade = offset < 0 ? 'early' : 'late';
48→    } else {
49→      // Stray tap — no matching beat nearby
50→      grade = 'early';
51→      offset = 0;
52→    }
53→
54→    const tap: TapEvent = {
55→      timestamp: tapTime,
56→      instrumentId,
57→      matchedStep,
58→      offset,
59→      grade,
60→    };
61→    this.taps.push(tap);
62→    return tap;
63→  }
64→
65→  sweepMisses(currentTime: number): ExpectedBeat[] {
66→    const missThreshold = currentTime - TIMING_THRESHOLDS.MAX_WINDOW;
67→    const misses: ExpectedBeat[] = [];
68→
69→    this.expectedBeats = this.expectedBeats.filter((beat) => {
70→      if (!beat.matched && beat.time < missThreshold) {
71→        misses.push(beat);
72→        return false;
73→      }
74→      if (beat.matched && beat.time < missThreshold) {
75→        return false;
76→      }
77→      return true;
78→    });
79→
80→    return misses;
81→  }
82→
83→  getTaps(): TapEvent[] {
84→    return this.taps;
85→  }
86→}
87→

  1→import { create } from 'zustand';
  2→import { InstrumentId } from '../patterns/types';
  3→import {
  4→  LiveMode,
  5→  TapEvent,
  6→  TimingGrade,
  7→  SessionStats,
  8→  StepAccuracy,
  9→  BarAccuracy,
 10→  KeyMapping,
 11→  DEFAULT_KEY_MAPPINGS,
 12→} from '../live-practice/types';
 13→
 14→function emptyStats(): SessionStats {
 15→  return {
 16→    totalExpected: 0,
 17→    totalHits: 0,
 18→    totalMisses: 0,
 19→    perfectCount: 0,
 20→    greatCount: 0,
 21→    goodCount: 0,
 22→    earlyLateCount: 0,
 23→    averageOffset: 0,
 24→    currentStreak: 0,
 25→    bestStreak: 0,
 26→    barHistory: [],
 27→  };
 28→}
 29→
 30→function isHit(grade: TimingGrade): boolean {
 31→  return grade === 'perfect' || grade === 'great' || grade === 'good';
 32→}
 33→
 34→interface LivePracticeStore {
 35→  mode: LiveMode;
 36→  focusedTrack: InstrumentId | null;
 37→  isActive: boolean;
 38→
 39→  stepAccuracies: Record<string, StepAccuracy>;
 40→  lastTapGrade: TimingGrade | null;
 41→  lastTapInstrument: InstrumentId | null;
 42→  lastTapOffset: number;
 43→  streakBroken: boolean;
 44→
 45→  barHistory: BarAccuracy[];
 46→  barHits: number;
 47→  barTotal: number;
 48→
 49→  stats: SessionStats;
 50→  keyMappings: KeyMapping[];
 51→
 52→  setMode: (mode: LiveMode) => void;
 53→  setFocusedTrack: (instrument: InstrumentId | null) => void;
 54→  startSession: () => void;
 55→  endSession: () => void;
 56→  recordTap: (tap: TapEvent) => void;
 57→  recordMiss: (step: number, instrumentId: InstrumentId) => void;
 58→  setStepAccuracy: (step: number, instrumentId: InstrumentId, grade: TimingGrade, offset: number) => void;
 59→  resetStepAccuracies: () => void;
 60→  recordBarEnd: () => void;
 61→  clearStreakBroken: () => void;
 62→}
 63→
 64→export const useLivePracticeStore = create<LivePracticeStore>((set, get) => ({
 65→  mode: 'full-kit',
 66→  focusedTrack: null,
 67→  isActive: false,
 68→
 69→  stepAccuracies: {},
 70→  lastTapGrade: null,
 71→  lastTapInstrument: null,
 72→  lastTapOffset: 0,
 73→  streakBroken: false,
 74→
 75→  barHistory: [],
 76→  barHits: 0,
 77→  barTotal: 0,
 78→
 79→  stats: emptyStats(),
 80→  keyMappings: DEFAULT_KEY_MAPPINGS,
 81→
 82→  setMode: (mode: LiveMode) => set({ mode }),
 83→
 84→  setFocusedTrack: (instrument: InstrumentId | null) => set({ focusedTrack: instrument }),
 85→
 86→  startSession: () =>
 87→    set({
 88→      isActive: true,
 89→      stats: emptyStats(),
 90→      stepAccuracies: {},
 91→      lastTapGrade: null,
 92→      lastTapInstrument: null,
 93→      lastTapOffset: 0,
 94→      streakBroken: false,
 95→      barHistory: [],
 96→      barHits: 0,
 97→      barTotal: 0,
 98→    }),
 99→
100→  endSession: () => set({ isActive: false }),
101→
102→  recordTap: (tap: TapEvent) => {
103→    const stats = { ...get().stats };
104→    const prevStreak = stats.currentStreak;
105→    let broken = false;
106→    let barHits = get().barHits;
107→    let barTotal = get().barTotal;
108→
109→    if (tap.matchedStep !== null) {
110→      stats.totalExpected++;
111→      barTotal++;
112→      if (isHit(tap.grade)) {
113→        stats.totalHits++;
114→        stats.currentStreak++;
115→        barHits++;
116→        if (stats.currentStreak > stats.bestStreak) {
117→          stats.bestStreak = stats.currentStreak;
118→        }
119→      } else {
120→        stats.earlyLateCount++;
121→        if (prevStreak > 2) broken = true;
122→        stats.currentStreak = 0;
123→      }
124→
125→      switch (tap.grade) {
126→        case 'perfect': stats.perfectCount++; break;
127→        case 'great': stats.greatCount++; break;
128→        case 'good': stats.goodCount++; break;
129→      }
130→
131→      // Incremental average offset
132→      const total = stats.totalHits + stats.earlyLateCount;
133→      if (total > 0) {
134→        stats.averageOffset =
135→          ((stats.averageOffset * (total - 1)) + tap.offset) / total;
136→      }
137→    }
138→
139→    set({
140→      stats,
141→      lastTapGrade: tap.grade,
142→      lastTapInstrument: tap.instrumentId,
143→      lastTapOffset: tap.offset,
144→      barHits,
145→      barTotal,
146→      ...(broken ? { streakBroken: true } : {}),
147→    });
148→  },
149→
150→  recordMiss: (step: number, instrumentId: InstrumentId) => {
151→    const stats = { ...get().stats };
152→    const prevStreak = stats.currentStreak;
153→    stats.totalExpected++;
154→    stats.totalMisses++;
155→    stats.currentStreak = 0;
156→
157→    const key = `${step}-${instrumentId}`;
158→    const accuracies = { ...get().stepAccuracies };
159→    accuracies[key] = { step, instrumentId, grade: 'miss', offset: 0 };
160→
161→    set({
162→      stats,
163→      stepAccuracies: accuracies,
164→      barTotal: get().barTotal + 1,
165→      ...(prevStreak > 2 ? { streakBroken: true } : {}),
166→    });
167→  },
168→
169→  setStepAccuracy: (step: number, instrumentId: InstrumentId, grade: TimingGrade, offset: number) => {
170→    const key = `${step}-${instrumentId}`;
171→    const accuracies = { ...get().stepAccuracies };
172→    accuracies[key] = { step, instrumentId, grade, offset };
173→    set({ stepAccuracies: accuracies });
174→  },
175→
176→  resetStepAccuracies: () => set({ stepAccuracies: {} }),
177→
178→  recordBarEnd: () => {
179→    const { barHits, barTotal, barHistory, stats } = get();
180→    if (barTotal === 0) return;
181→    const accuracy = Math.round((barHits / barTotal) * 100);
182→    const entry: BarAccuracy = { accuracy, hits: barHits, total: barTotal };
183→    const newHistory = [...barHistory, entry].slice(-16);
184→    const newStats = { ...stats, barHistory: [...stats.barHistory, entry] };
185→    set({ barHistory: newHistory, barHits: 0, barTotal: 0, stats: newStats });
186→  },
187→
188→  clearStreakBroken: () => set({ streakBroken: false }),
189→}));
190→

  1→'use client';
  2→
  3→import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
  4→import { useRouter } from 'next/navigation';
  5→import { Header } from '@/components/Header';
  6→import { BeatGrid } from '@/components/sequencer/BeatGrid';
  7→import { TransportControls } from '@/components/controls/TransportControls';
  8→import { BpmControl } from '@/components/controls/BpmControl';
  9→import { TapPadPanel } from '@/components/live/TapPadPanel';
 10→import { LiveStatsPanel } from '@/components/live/LiveStatsPanel';
 11→import { LiveResultsModal } from '@/components/live/LiveResultsModal';
 12→import { ModeSelector } from '@/components/live/ModeSelector';
 13→import { GradeToast } from '@/components/live/GradeToast';
 14→import { TimingIndicator } from '@/components/live/TimingIndicator';
 15→import { StreakDisplay } from '@/components/live/StreakDisplay';
 16→import { BarHistoryStrip } from '@/components/live/BarHistoryStrip';
 17→import { usePatternStore } from '@/lib/store/usePatternStore';
 18→import { useTransportStore, scheduler } from '@/lib/store/useTransportStore';
 19→import { useLivePracticeStore } from '@/lib/store/useLivePracticeStore';
 20→import { useLiveKeyboardHandler } from '@/lib/hooks/useLiveKeyboardHandler';
 21→import { TapMatcher } from '@/lib/live-practice/TapMatcher';
 22→import { audioEngine } from '@/lib/audio/AudioEngine';
 23→import { TimingGrade } from '@/lib/live-practice/types';
 24→import { Track } from '@/lib/patterns/types';
 25→import { usePracticeHistoryStore } from '@/lib/store/usePracticeHistoryStore';
 26→
 27→export default function LivePracticePage() {
 28→  const pattern = usePatternStore((s) => s.currentPattern);
 29→  const playState = useTransportStore((s) => s.playState);
 30→  const play = useTransportStore((s) => s.play);
 31→  const stop = useTransportStore((s) => s.stop);
 32→  const bpm = useTransportStore((s) => s.bpm);
 33→
 34→  const isActive = useLivePracticeStore((s) => s.isActive);
 35→  const startSession = useLivePracticeStore((s) => s.startSession);
 36→  const endSession = useLivePracticeStore((s) => s.endSession);
 37→  const mode = useLivePracticeStore((s) => s.mode);
 38→  const focusedTrack = useLivePracticeStore((s) => s.focusedTrack);
 39→  const stepAccuraciesRaw = useLivePracticeStore((s) => s.stepAccuracies);
 40→  const recordMiss = useLivePracticeStore((s) => s.recordMiss);
 41→  const resetStepAccuracies = useLivePracticeStore((s) => s.resetStepAccuracies);
 42→  const stats = useLivePracticeStore((s) => s.stats);
 43→
 44→  const addHistorySession = usePracticeHistoryStore((s) => s.addSession);
 45→  const updateCard = usePracticeHistoryStore((s) => s.updateCard);
 46→
 47→  const [showResults, setShowResults] = useState(false);
 48→
 49→  const tapMatcherRef = useRef<TapMatcher | null>(null);
 50→  const sweepIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
 51→  const sessionStartRef = useRef<number>(0);
 52→
 53→  // Initialize TapMatcher
 54→  if (!tapMatcherRef.current) {
 55→    tapMatcherRef.current = new TapMatcher();
 56→  }
 57→
 58→  // Convert stepAccuracies to the format BeatGrid expects: Record<string, TimingGrade>
 59→  const stepAccuracies = useMemo(() => {
 60→    const result: Record<string, TimingGrade> = {};
 61→    for (const [key, acc] of Object.entries(stepAccuraciesRaw)) {
 62→      result[key] = acc.grade;
 63→    }
 64→    return result;
 65→  }, [stepAccuraciesRaw]);
 66→
 67→  // Register step listener for feeding expected beats to TapMatcher
 68→  useEffect(() => {
 69→    const unsubscribe = scheduler.addStepListener((step, time) => {
 70→      const tapMatcher = tapMatcherRef.current;
 71→      if (!tapMatcher || !useLivePracticeStore.getState().isActive) return;
 72→
 73→      const liveMode = useLivePracticeStore.getState().mode;
 74→      const focused = useLivePracticeStore.getState().focusedTrack;
 75→      const currentPattern = usePatternStore.getState().currentPattern;
 76→
 77→      currentPattern.tracks.forEach((track: Track) => {
 78→        const s = track.steps[step];
 79→        if (!s || !s.active) return;
 80→
 81→        // In single-track mode, only expect beats for the focused instrument
 82→        if (liveMode === 'single-track' && focused && track.instrumentId !== focused) return;
 83→
 84→        tapMatcher.addExpectedBeat(step, time, track.instrumentId);
 85→      });
 86→    });
 87→
 88→    return unsubscribe;
 89→  }, []);
 90→
 91→  // Sweep for misses periodically
 92→  useEffect(() => {
 93→    if (isActive) {
 94→      sweepIntervalRef.current = setInterval(() => {
 95→        const tapMatcher = tapMatcherRef.current;
 96→        if (!tapMatcher) return;
 97→        const misses = tapMatcher.sweepMisses(audioEngine.currentTime);
 98→        misses.forEach((miss) => {
 99→          recordMiss(miss.step, miss.instrumentId);
100→        });
101→      }, 50);
102→    } else {
103→      if (sweepIntervalRef.current) {
104→        clearInterval(sweepIntervalRef.current);
105→      }
106→    }
107→
108→    return () => {
109→      if (sweepIntervalRef.current) {
110→        clearInterval(sweepIntervalRef.current);
111→      }
112→    };
113→  }, [isActive, recordMiss]);
114→
115→  // Record bar accuracy + reset step accuracy display each bar
116→  useEffect(() => {
117→    const unsubscribe = scheduler.addStepListener((step) => {
118→      if (step === 0 && useLivePracticeStore.getState().isActive) {
119→        useLivePracticeStore.getState().recordBarEnd();
120→        useLivePracticeStore.getState().resetStepAccuracies();
121→      }
122→    });
123→    return unsubscribe;
124→  }, []);
125→
126→  // Handle keyboard taps
127→  useLiveKeyboardHandler(tapMatcherRef.current, isActive);
128→
129→  // Handle play/stop with session tracking
130→  const handlePlay = useCallback(() => {
131→    tapMatcherRef.current?.reset();
132→    sessionStartRef.current = Date.now();
133→    startSession();
134→    resetStepAccuracies();
135→    play();
136→  }, [play, startSession, resetStepAccuracies]);
137→
138→  const handleStop = useCallback(() => {
139→    const sessionEndTime = Date.now();
140→    stop();
141→    // Final sweep for any remaining expected beats
142→    if (tapMatcherRef.current) {
143→      const misses = tapMatcherRef.current.sweepMisses(Infinity);
144→      const rm = useLivePracticeStore.getState().recordMiss;
145→      misses.forEach((miss) => rm(miss.step, miss.instrumentId));
146→    }
147→    endSession();
148→
149→    // Persist session to history
150→    const finalStats = useLivePracticeStore.getState().stats;
151→    const currentPattern = usePatternStore.getState().currentPattern;
152→    const currentBpm = useTransportStore.getState().bpm;
153→    const durationMs = sessionEndTime - sessionStartRef.current;
154→
155→    if (finalStats.totalExpected > 0 && durationMs > 5000) {
156→      const accuracy = Math.round(
157→        (finalStats.totalHits / finalStats.totalExpected) * 100
158→      );
159→      addHistorySession({
160→        patternId: currentPattern.id,
161→        patternName: currentPattern.name,
162→        mode: 'live',
163→        startedAt: sessionStartRef.current,
164→        endedAt: sessionEndTime,
165→        durationMs,
166→        bpm: currentBpm,
167→        accuracy,
168→        stats: { ...finalStats },
169→      });
170→      updateCard(currentPattern.id, accuracy);
171→      setShowResults(true);
172→    }
173→  }, [stop, endSession, addHistorySession, updateCard]);
174→
175→  const handleRetry = useCallback(() => {
176→    setShowResults(false);
177→    handlePlay();
178→  }, [handlePlay]);
179→
180→  const router = useRouter();
181→  const handleBackToPatterns = useCallback(() => {
182→    setShowResults(false);
183→    router.push('/');
184→  }, [router]);
185→
186→  return (
187→    <div className="min-h-screen">
188→      <Header />
189→      <main className="max-w-5xl mx-auto px-4 py-6">
190→        {/* Pattern info + mode */}
191→        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-4">
192→          <div>
193→            <div className="flex items-center gap-3 mb-1">
194→              <h1 className="text-xl font-bold">{pattern.name}</h1>
195→              <span className="text-xs bg-gray-800 text-gray-400 px-2 py-0.5 rounded-full">
196→                {pattern.timeSignature.beats}/{pattern.timeSignature.noteValue}
197→              </span>
198→              <span className="text-xs bg-gray-800 text-gray-400 px-2 py-0.5 rounded-full">
199→                {pattern.subdivision}
200→              </span>
201→            </div>
202→            <p className="text-sm text-gray-500">{pattern.description}</p>
203→          </div>
204→          <ModeSelector />
205→        </div>
206→
207→        {/* Beat grid with accuracy overlay */}
208→        <div className="mb-2 overflow-x-auto">
209→          <BeatGrid stepAccuracies={isActive || stats.totalExpected > 0 ? stepAccuracies : undefined} />
210→        </div>
211→
212→        {/* Bar history strip */}
213→        <div className="mb-4">
214→          <BarHistoryStrip />
215→        </div>
216→
217→        {/* Grade toast + timing + streak */}
218→        <div className="mb-4 space-y-1">
219→          <GradeToast />
220→          <TimingIndicator />
221→          <StreakDisplay />
222→        </div>
223→
224→        {/* Controls + pads + stats */}
225→        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
226→          {/* Transport + BPM */}
227→          <div className="flex flex-col gap-4">
228→            <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
229→              <div className="flex items-center gap-3 mb-4">
230→                {/* Custom play/stop that manages sessions */}
231→                <button
232→                  onClick={playState === 'playing' ? handleStop : handlePlay}
233→                  className="w-14 h-14 rounded-full bg-white text-gray-900 flex items-center justify-center
234→                             hover:bg-gray-200 active:scale-95 transition-all cursor-pointer shadow-lg"
235→                  aria-label={playState === 'playing' ? 'Stop' : 'Start'}
236→                >
237→                  {playState === 'playing' ? (
238→                    <svg width="14" height="14" viewBox="0 0 14 14" fill="currentColor">
239→                      <rect x="1" y="1" width="12" height="12" rx="2" />
240→                    </svg>
241→                  ) : (
242→                    <svg width="20" height="20" viewBox="0 0 20 20" fill="currentColor">
243→                      <path d="M5 3.5L16.5 10L5 16.5V3.5Z" />
244→                    </svg>
245→                  )}
246→                </button>
247→                {isActive && (
248→                  <div className="flex items-center gap-1.5">
249→                    <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
250→                    <span className="text-xs text-gray-400 uppercase tracking-wider">Live</span>
251→                  </div>
252→                )}
253→              </div>
254→              <BpmControl />
255→            </div>
256→          </div>
257→
258→          {/* Tap pads */}
259→          <TapPadPanel tapMatcher={tapMatcherRef.current} isActive={isActive} />
260→
261→          {/* Stats */}
262→          <LiveStatsPanel />
263→        </div>
264→
265→        {/* Help text */}
266→        <div className="mt-4 text-center text-xs text-gray-600">
267→          Press the mapped keys to tap along with the beat.
268→          <span className="mx-2">|</span>
