12→  if (!lastGrade || lastGrade === 'miss') return null;
13→
14→  // Clamp offset to ±100ms for display, map to -1..1 range
15→  const offsetMs = lastOffset * 1000;
16→  const clamped = Math.max(-100, Math.min(100, offsetMs));
17→  const position = (clamped + 100) / 200; // 0 = -100ms (early), 1 = +100ms (late)
18→
19→  // Color based on distance from center
20→  const absOffset = Math.abs(clamped);
21→  let dotColor: string;
22→  if (absOffset < 15) dotColor = 'bg-green-400';
23→  else if (absOffset < 30) dotColor = 'bg-lime-400';
24→  else if (absOffset < 50) dotColor = 'bg-yellow-400';
25→  else dotColor = 'bg-orange-400';
