34→        </div>
35→        {/* Center tick */}
36→        <div className="absolute top-0 bottom-0 left-1/2 w-px bg-gray-600" />
37→        {/* Quarter ticks */}
38→        <div className="absolute top-1.5 bottom-1.5 left-1/4 w-px bg-gray-800" />
39→        <div className="absolute top-1.5 bottom-1.5 left-3/4 w-px bg-gray-800" />
