141→export function getPracticedDays(): Set<string> {
142→  const days = new Set<string>();
143→  usePracticeHistoryStore.getState().sessions.forEach((s) => {
144→    const d = new Date(s.startedAt);
145→    days.add(
146→      `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
147→    );
148→  });
149→  return days;
150→}
