25→    mode === 'interval' &&
26→    !challengeActive &&
27→    targetNotes.length === 2 &&
28→    results.length >= 2;
29→
30→  const intervalSemitones = showIntervalName
31→    ? Math.abs(
32→        ALL_NOTES[targetNotes[1]].midiNumber -
33→          ALL_NOTES[targetNotes[0]].midiNumber
34→      )
35→    : 0;
36→
37→  return (
38→    <div className="h-10 flex items-center justify-center gap-3">
39→      {visible && lastResult && (
40→        <span
41→          className={`
42→            text-lg font-bold animate-pulse
43→            ${lastResult === 'correct' ? 'text-green-400' : 'text-red-400'}
44→          `}
45→        >
46→          {lastResult === 'correct' ? 'Correct!' : 'Wrong'}
47→        </span>
48→      )}
49→      {showIntervalName && (
50→        <span className="text-sm text-indigo-400 font-medium">
51→          {getIntervalName(intervalSemitones)}
52→        </span>
53→      )}
54→      {!challengeActive && results.length > 0 && mode === 'phrase' && (
55→        <span className="text-sm text-gray-400">
56→          {results.filter((r) => r.correct).length}/{results.length} correct
57→        </span>
58→      )}
59→    </div>
60→  );
61→}
