 1→class AudioEngine {
 2→  private ctx: AudioContext | null = null;
 3→  private masterGain: GainNode | null = null;
 4→  private compressor: DynamicsCompressorNode | null = null;
 5→  private _noiseBuffer: AudioBuffer | null = null;
 6→
 7→  init(): AudioContext {
 8→    if (!this.ctx) {
 9→      this.ctx = new AudioContext();
10→      this.compressor = this.ctx.createDynamicsCompressor();
11→      this.compressor.threshold.value = -12;
12→      this.compressor.knee.value = 10;
13→      this.compressor.ratio.value = 4;
14→      this.masterGain = this.ctx.createGain();
15→      this.masterGain.connect(this.compressor);
16→      this.compressor.connect(this.ctx.destination);
17→
18→      // Pre-generate noise buffer (2 seconds)
19→      const bufferSize = this.ctx.sampleRate * 2;
20→      this._noiseBuffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
21→      const data = this._noiseBuffer.getChannelData(0);
22→      for (let i = 0; i < bufferSize; i++) {
23→        data[i] = Math.random() * 2 - 1;
24→      }
25→    }
26→
27→    if (this.ctx.state === 'suspended') {
28→      this.ctx.resume();
29→    }
30→    return this.ctx;
31→  }
32→
33→  get context(): AudioContext | null {
34→    return this.ctx;
35→  }
36→
37→  get currentTime(): number {
38→    return this.ctx?.currentTime ?? 0;
39→  }
40→
41→  get destination(): GainNode {
42→    return this.masterGain!;
43→  }
44→
45→  get noiseBuffer(): AudioBuffer | null {
46→    return this._noiseBuffer;
47→  }
48→
49→  setMasterVolume(value: number): void {
50→    if (this.masterGain && this.ctx) {
51→      this.masterGain.gain.setValueAtTime(value, this.ctx.currentTime);
52→    }
53→  }
54→}
55→
56→export const audioEngine = new AudioEngine();
