  1→import { create } from 'zustand';
  2→import { InstrumentId } from '../patterns/types';
  3→import {
  4→  LiveMode,
  5→  TapEvent,
  6→  TimingGrade,
  7→  SessionStats,
  8→  StepAccuracy,
  9→  BarAccuracy,
 10→  KeyMapping,
 11→  DEFAULT_KEY_MAPPINGS,
 12→} from '../live-practice/types';
 13→
 14→function emptyStats(): SessionStats {
 15→  return {
 16→    totalExpected: 0,
 17→    totalHits: 0,
 18→    totalMisses: 0,
 19→    perfectCount: 0,
 20→    greatCount: 0,
 21→    goodCount: 0,
 22→    earlyLateCount: 0,
 23→    averageOffset: 0,
 24→    currentStreak: 0,
 25→    bestStreak: 0,
 26→    barHistory: [],
 27→  };
 28→}
