 34→interface LivePracticeStore {
 35→  mode: LiveMode;
 36→  focusedTrack: InstrumentId | null;
 37→  isActive: boolean;
 38→
 39→  stepAccuracies: Record<string, StepAccuracy>;
 40→  lastTapGrade: TimingGrade | null;
 41→  lastTapInstrument: InstrumentId | null;
 42→  lastTapOffset: number;
 43→  perTrackOffset: Record<string, { offset: number; grade: TimingGrade }>;
 44→  streakBroken: boolean;
 45→
 46→  barHistory: BarAccuracy[];
 47→  barHits: number;
 48→  barTotal: number;
 49→
 50→  stats: SessionStats;
 51→  keyMappings: KeyMapping[];
 52→
 53→  setMode: (mode: LiveMode) => void;
 54→  setFocusedTrack: (instrument: InstrumentId | null) => void;
 55→  startSession: () => void;
 56→  endSession: () => void;
 57→  recordTap: (tap: TapEvent) => void;
 58→  recordMiss: (step: number, instrumentId: InstrumentId) => void;
 59→  setStepAccuracy: (step: number, instrumentId: InstrumentId, grade: TimingGrade, offset: number) => void;
 60→  resetStepAccuracies: () => void;
 61→  recordBarEnd: () => void;
 62→  clearStreakBroken: () => void;
 63→}
 64→
 65→export const useLivePracticeStore = create<LivePracticeStore>((set, get) => ({
 66→  mode: 'full-kit',
 67→  focusedTrack: null,
 68→  isActive: false,
 69→
 70→  stepAccuracies: {},
 71→  lastTapGrade: null,
 72→  lastTapInstrument: null,
 73→  lastTapOffset: 0,
 74→  perTrackOffset: {},
 75→  streakBroken: false,
 76→
 77→  barHistory: [],
 78→  barHits: 0,
 79→  barTotal: 0,
 80→
 81→  stats: emptyStats(),
 82→  keyMappings: DEFAULT_KEY_MAPPINGS,
 83→
 84→  setMode: (mode: LiveMode) => set({ mode }),
 85→
 86→  setFocusedTrack: (instrument: InstrumentId | null) => set({ focusedTrack: instrument }),
 87→
 88→  startSession: () =>
 89→    set({
 90→      isActive: true,
 91→      stats: emptyStats(),
 92→      stepAccuracies: {},
 93→      lastTapGrade: null,
 94→      lastTapInstrument: null,
 95→      lastTapOffset: 0,
 96→      perTrackOffset: {},
 97→      streakBroken: false,
 98→      barHistory: [],
 99→      barHits: 0,
100→      barTotal: 0,
101→    }),
102→
103→  endSession: () => set({ isActive: false }),
104→
105→  recordTap: (tap: TapEvent) => {
106→    const stats = { ...get().stats };
107→    const prevStreak = stats.currentStreak;
108→    let broken = false;
109→    let barHits = get().barHits;
110→    let barTotal = get().barTotal;
111→
112→    if (tap.matchedStep !== null) {
113→      stats.totalExpected++;
114→      barTotal++;
115→      if (isHit(tap.grade)) {
116→        stats.totalHits++;
117→        stats.currentStreak++;
118→        barHits++;
119→        if (stats.currentStreak > stats.bestStreak) {
120→          stats.bestStreak = stats.currentStreak;
121→        }
122→      } else {
123→        stats.earlyLateCount++;
124→        if (prevStreak > 2) broken = true;
125→        stats.currentStreak = 0;
126→      }
127→
128→      switch (tap.grade) {
129→        case 'perfect': stats.perfectCount++; break;
130→        case 'great': stats.greatCount++; break;
131→        case 'good': stats.goodCount++; break;
132→      }
133→
134→      // Incremental average offset
135→      const total = stats.totalHits + stats.earlyLateCount;
136→      if (total > 0) {
137→        stats.averageOffset =
138→          ((stats.averageOffset * (total - 1)) + tap.offset) / total;
139→      }
140→    }
141→
142→    const perTrackOffset = { ...get().perTrackOffset };
143→    if (tap.matchedStep !== null) {
144→      perTrackOffset[tap.instrumentId] = { offset: tap.offset, grade: tap.grade };
145→    }
146→
147→    set({
148→      stats,
149→      lastTapGrade: tap.grade,
150→      lastTapInstrument: tap.instrumentId,
151→      lastTapOffset: tap.offset,
152→      perTrackOffset,
153→      barHits,
154→      barTotal,
155→      ...(broken ? { streakBroken: true } : {}),
156→    });
157→  },
158→
159→  recordMiss: (step: number, instrumentId: InstrumentId) => {
160→    const stats = { ...get().stats };
161→    const prevStreak = stats.currentStreak;
162→    stats.totalExpected++;
163→    stats.totalMisses++;
164→    stats.currentStreak = 0;
165→
166→    const key = `${step}-${instrumentId}`;
167→    const accuracies = { ...get().stepAccuracies };
168→    accuracies[key] = { step, instrumentId, grade: 'miss', offset: 0 };
169→
170→    set({
171→      stats,
172→      stepAccuracies: accuracies,
173→      barTotal: get().barTotal + 1,
174→      ...(prevStreak > 2 ? { streakBroken: true } : {}),
175→    });
176→  },
177→
178→  setStepAccuracy: (step: number, instrumentId: InstrumentId, grade: TimingGrade, offset: number) => {
179→    const key = `${step}-${instrumentId}`;
180→    const accuracies = { ...get().stepAccuracies };
181→    accuracies[key] = { step, instrumentId, grade, offset };
182→    set({ stepAccuracies: accuracies });
183→  },
184→
185→  resetStepAccuracies: () => set({ stepAccuracies: {} }),
186→
187→  recordBarEnd: () => {
188→    const { barHits, barTotal, barHistory, stats } = get();
189→    if (barTotal === 0) return;
190→    const accuracy = Math.round((barHits / barTotal) * 100);
191→    const entry: BarAccuracy = { accuracy, hits: barHits, total: barTotal };
192→    const newHistory = [...barHistory, entry].slice(-16);
193→    const newStats = { ...stats, barHistory: [...stats.barHistory, entry] };
194→    set({ barHistory: newHistory, barHits: 0, barTotal: 0, stats: newStats });
195→  },
196→
197→  clearStreakBroken: () => set({ streakBroken: false }),
198→}));
