 3→import { useEffect, useRef, useState } from 'react';
 4→import { useLivePracticeStore } from '@/lib/store/useLivePracticeStore';
 5→import { GRADE_TEXT_COLORS } from '@/lib/live-practice/types';
 6→
 7→interface ToastEntry {
 8→  id: number;
 9→  grade: string;
10→  offsetMs: number;
11→}
12→
13→let toastId = 0;
14→
15→export function GradeToast() {
16→  const lastGrade = useLivePracticeStore((s) => s.lastTapGrade);
17→  const lastOffset = useLivePracticeStore((s) => s.lastTapOffset);
18→  const isActive = useLivePracticeStore((s) => s.isActive);
19→
20→  const [toasts, setToasts] = useState<ToastEntry[]>([]);
21→  const prevGradeRef = useRef(lastGrade);
22→
23→  useEffect(() => {
24→    if (!isActive || !lastGrade) return;
25→    // Only trigger on change (new tap)
26→    if (lastGrade === prevGradeRef.current && toasts.length > 0) return;
27→    prevGradeRef.current = lastGrade;
28→
29→    const id = ++toastId;
30→    const offsetMs = Math.round(lastOffset * 1000);
31→    setToasts((prev) => [...prev.slice(-3), { id, grade: lastGrade, offsetMs }]);
32→
33→    const timer = setTimeout(() => {
34→      setToasts((prev) => prev.filter((t) => t.id !== id));
35→    }, 600);
36→
37→    return () => clearTimeout(timer);
38→  }, [lastGrade, lastOffset, isActive]);
39→
40→  // Reset on session end
41→  useEffect(() => {
42→    if (!isActive) setToasts([]);
43→  }, [isActive]);
44→
45→  if (toasts.length === 0) return null;
46→
47→  return (
48→    <div className="relative h-8 flex items-center justify-center overflow-hidden">
49→      {toasts.map((toast) => {
50→        const color = GRADE_TEXT_COLORS[toast.grade as keyof typeof GRADE_TEXT_COLORS] ?? 'text-gray-400';
51→        const label = toast.grade.charAt(0).toUpperCase() + toast.grade.slice(1);
52→        const offsetLabel = toast.grade === 'miss'
53→          ? ''
54→          : toast.offsetMs === 0
55→            ? ''
56→            : toast.offsetMs > 0
57→              ? ` +${toast.offsetMs}ms`
58→              : ` ${toast.offsetMs}ms`;
59→
60→        return (
61→          <span
62→            key={toast.id}
63→            className={`absolute text-sm font-bold uppercase ${color} animate-grade-toast`}
64→          >
65→            {label}{offsetLabel && <span className="text-xs font-normal opacity-70">{offsetLabel}</span>}
66→          </span>
67→        );
68→      })}
69→
70→      <style>{`
71→        @keyframes grade-toast {
72→          0% { opacity: 0; transform: translateY(8px) scale(0.9); }
73→          20% { opacity: 1; transform: translateY(0) scale(1); }
74→          80% { opacity: 1; transform: translateY(-4px) scale(1); }
75→          100% { opacity: 0; transform: translateY(-12px) scale(0.95); }
76→        }
77→        .animate-grade-toast {
78→          animation: grade-toast 600ms ease-out forwards;
79→        }
80→      `}</style>
81→    </div>
82→  );
83→}
