 7→function getDotColor(absOffset: number): string {
 8→  if (absOffset < 15) return 'bg-green-400';
 9→  if (absOffset < 30) return 'bg-lime-400';
10→  if (absOffset < 50) return 'bg-yellow-400';
11→  return 'bg-orange-400';
12→}
13→
14→function TrackTimingRow({ instrumentId, label }: { instrumentId: InstrumentId; label: string }) {
15→  const data = useLivePracticeStore((s) => s.perTrackOffset[instrumentId]);
16→
17→  if (!data || data.grade === 'miss') {
18→    return (
19→      <div className="flex items-center gap-2">
20→        <span className="text-[10px] text-gray-600 w-14 truncate">{label}</span>
21→        <div className="relative flex-1 h-4">
22→          <div className="absolute inset-y-0 left-0 right-0 flex items-center">
23→            <div className="w-full h-0.5 bg-gray-800 rounded-full" />
24→          </div>
25→          <div className="absolute top-0 bottom-0 left-1/2 w-px bg-gray-700" />
26→        </div>
27→      </div>
28→    );
29→  }
30→
31→  const offsetMs = data.offset * 1000;
32→  const clamped = Math.max(-100, Math.min(100, offsetMs));
33→  const position = (clamped + 100) / 200;
34→  const dotColor = getDotColor(Math.abs(clamped));
35→  const offsetLabel = Math.round(offsetMs);
36→
37→  return (
38→    <div className="flex items-center gap-2">
39→      <span className="text-[10px] text-gray-500 w-14 truncate">{label}</span>
40→      <div className="relative flex-1 h-4">
41→        <div className="absolute inset-y-0 left-0 right-0 flex items-center">
42→          <div className="w-full h-0.5 bg-gray-800 rounded-full" />
43→        </div>
44→        <div className="absolute top-0 bottom-0 left-1/2 w-px bg-gray-700" />
45→        <div
46→          className={`absolute top-1/2 w-2.5 h-2.5 rounded-full ${dotColor} transition-all duration-75`}
47→          style={{
48→            left: `${position * 100}%`,
49→            transform: 'translate(-50%, -50%)',
50→          }}
51→        />
52→      </div>
53→      <span className="text-[9px] text-gray-600 w-10 text-right tabular-nums">
54→        {offsetLabel > 0 ? '+' : ''}{offsetLabel}ms
55→      </span>
56→    </div>
57→  );
58→}
