 33→
 34→  const isActive = useLivePracticeStore((s) => s.isActive);
 35→  const startSession = useLivePracticeStore((s) => s.startSession);
 36→  const endSession = useLivePracticeStore((s) => s.endSession);
 37→  const mode = useLivePracticeStore((s) => s.mode);
