25→export function OverallStatsRow() {
26→  const sessions = usePracticeHistoryStore((s) => s.sessions);
27→
28→  const totalMs = getTotalPracticeMs();
29→  const days = getPracticedDays();
30→  const streak = computeStreak(days);
31→  const uniquePatterns = new Set(sessions.map((s) => s.patternId)).size;
32→
33→  // Average accuracy across live sessions
34→  const liveSessions = sessions.filter((s) => s.accuracy !== null);
35→  const avgAccuracy = liveSessions.length > 0
36→    ? Math.round(liveSessions.reduce((sum, s) => sum + s.accuracy!, 0) / liveSessions.length)
37→    : null;
38→
39→  const tiles = [
40→    { label: 'Total Time', value: sessions.length > 0 ? formatDuration(totalMs) : '--' },
41→    { label: 'Sessions', value: sessions.length.toString() },
42→    { label: 'Patterns', value: uniquePatterns.toString() },
43→    { label: 'Day Streak', value: streak > 0 ? `${streak}d` : '--' },
44→    { label: 'Avg Accuracy', value: avgAccuracy !== null ? `${avgAccuracy}%` : '--' },
45→  ];
46→
47→  return (
48→    <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
49→      {tiles.map((tile) => (
50→        <div
51→          key={tile.label}
52→          className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800 text-center"
