10→
11→const instrumentPadColors: Record<InstrumentId, string> = {
12→  kick: 'border-red-500/50 hover:border-red-500',
13→  snare: 'border-yellow-400/50 hover:border-yellow-400',
14→  'hihat-closed': 'border-cyan-400/50 hover:border-cyan-400',
