 38→}
 39→
 40→export const usePracticeHistoryStore = create<PracticeHistoryState>()(
 41→  persist(
 42→    (set, get) => ({
 43→      sessions: [],
 44→      cards: {},
 45→
 46→      addSession: (sessionData) => {
 47→        const session: PracticeSession = {
 48→          ...sessionData,
 49→          id: crypto.randomUUID(),
 50→        };
 51→        set((state) => ({
 52→          sessions: [session, ...state.sessions].slice(0, MAX_SESSIONS),
 53→        }));
 54→      },
 55→
 56→      updateCard: (patternId, accuracy) => {
 57→        const existing = get().cards[patternId];
 58→        const current = existing ?? {
 59→          easeFactor: 2.5,
 60→          intervalDays: 1,
 61→          repetitions: 0,
 62→        };
 63→        const quality = accuracyToQuality(accuracy);
 64→        const result = computeNextReview(current, quality);
 65→
 66→        set((state) => ({
 67→          cards: {
 68→            ...state.cards,
 69→            [patternId]: {
 70→              patternId,
 71→              easeFactor: result.easeFactor,
 72→              intervalDays: result.intervalDays,
 73→              repetitions: result.repetitions,
 74→              lastReviewedAt: Date.now(),
 75→              nextReviewAt: result.nextReviewAt,
 76→              lastAccuracy: accuracy,
 77→            },
 78→          },
 79→        }));
 80→      },
 81→
 82→      clearHistory: () => set({ sessions: [], cards: {} }),
 83→    }),
 84→    {
 85→      name: 'drum-practice-history',
 86→      partialize: (state) => ({
 87→        sessions: state.sessions,
 88→        cards: state.cards,
 89→      }),
 90→    }
 91→  )
 92→);
 93→
 94→// Selector helpers (use outside React or in callbacks)
 95→
 96→export function getSessionsForPattern(patternId: string): PracticeSession[] {
 97→  return usePracticeHistoryStore
 98→    .getState()
 99→    .sessions.filter((s) => s.patternId === patternId);
100→}
101→
102→export function getLastLiveSessionForPattern(patternId: string): PracticeSession | null {
103→  const sessions = usePracticeHistoryStore.getState().sessions;
104→  // Sessions are stored most-recent-first; skip index 0 (current session just saved)
105→  for (let i = 1; i < sessions.length; i++) {
106→    if (sessions[i].patternId === patternId && sessions[i].mode === 'live') {
107→      return sessions[i];
108→    }
109→  }
110→  return null;
111→}
112→
113→export function getDuePatterns(): string[] {
114→  const { cards } = usePracticeHistoryStore.getState();
115→
116→  // Patterns with cards that are due
117→  const due = Object.values(cards)
118→    .filter(isCardDue)
119→    .sort((a, b) => {
120→      if (a.nextReviewAt === null) return 1;
121→      if (b.nextReviewAt === null) return -1;
122→      return a.nextReviewAt - b.nextReviewAt;
123→    })
124→    .map((card) => card.patternId);
125→
126→  // Patterns never practiced in live mode
127→  const practiced = new Set(Object.keys(cards));
128→  const neverPracticed = allPatterns
129→    .filter((p) => !practiced.has(p.id))
130→    .map((p) => p.id);
131→
132→  return [...due, ...neverPracticed];
133→}
134→
135→export function getTotalPracticeMs(): number {
136→  return usePracticeHistoryStore
137→    .getState()
138→    .sessions.reduce((sum, s) => sum + s.durationMs, 0);
139→}
140→
141→export function getPracticedDays(): Set<string> {
142→  const days = new Set<string>();
143→  usePracticeHistoryStore.getState().sessions.forEach((s) => {
144→    const d = new Date(s.startedAt);
145→    days.add(
146→      `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
147→    );
148→  });
149→  return days;
150→}
