222→
223→        {/* Controls + pads + stats */}
224→        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
225→          {/* Transport + BPM */}
226→          <div className="flex flex-col gap-4">
227→            <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
228→              <div className="flex items-center gap-3 mb-4">
229→                {/* Custom play/stop that manages sessions */}
230→                <button
231→                  onClick={playState === 'playing' ? handleStop : handlePlay}
232→                  className="w-14 h-14 rounded-full bg-white text-gray-900 flex items-center justify-center
233→                             hover:bg-gray-200 active:scale-95 transition-all cursor-pointer shadow-lg"
234→                  aria-label={playState === 'playing' ? 'Stop' : 'Start'}
235→                >
236→                  {playState === 'playing' ? (
237→                    <svg width="14" height="14" viewBox="0 0 14 14" fill="currentColor">
