11→const instrumentPadColors: Record<InstrumentId, string> = {
12→  kick: 'border-red-500/50 hover:border-red-500',
13→  snare: 'border-yellow-400/50 hover:border-yellow-400',
14→  'hihat-closed': 'border-cyan-400/50 hover:border-cyan-400',
15→  'hihat-open': 'border-cyan-300/50 hover:border-cyan-300',
16→  'tom-high': 'border-purple-400/50 hover:border-purple-400',
17→  'tom-mid': 'border-purple-500/50 hover:border-purple-500',
18→  'tom-low': 'border-purple-600/50 hover:border-purple-600',
19→  crash: 'border-orange-400/50 hover:border-orange-400',
20→  ride: 'border-green-400/50 hover:border-green-400',
21→};
