31→export const TapPad = React.memo(function TapPad({
32→  instrumentId,
33→  label,
34→  keyLabel,
35→  tapMatcher,
36→  isActive,
37→}: TapPadProps) {
38→  const [flash, setFlash] = useState<TimingGrade | null>(null);
39→  const flashTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
40→
41→  const handleTap = useCallback(() => {
42→    if (!tapMatcher || !isActive) return;
43→
44→    const tapTime = audioEngine.currentTime;
45→    playInstrument(instrumentId, tapTime, 0.8, 0.8);
46→
47→    const tapEvent = tapMatcher.processTap(tapTime, instrumentId);
48→    const store = useLivePracticeStore.getState();
49→    store.recordTap(tapEvent);
50→    if (tapEvent.matchedStep !== null) {
51→      store.setStepAccuracy(
52→        tapEvent.matchedStep,
53→        instrumentId,
54→        tapEvent.grade,
55→        tapEvent.offset
56→      );
57→    }
58→
59→    // Visual flash
60→    setFlash(tapEvent.grade);
61→    if (flashTimeout.current) clearTimeout(flashTimeout.current);
62→    flashTimeout.current = setTimeout(() => setFlash(null), 200);
63→  }, [instrumentId, tapMatcher, isActive]);
64→
65→  const padColor = instrumentPadColors[instrumentId];
66→  const flashColor = flash ? GRADE_COLORS[flash] : '';
67→
68→  return (
69→    <button
70→      onMouseDown={(e) => { e.preventDefault(); handleTap(); }}
71→      onTouchStart={(e) => { e.preventDefault(); handleTap(); }}
72→      className={`
73→        relative flex flex-col items-center justify-center
74→        w-16 h-16 sm:w-20 sm:h-20 rounded-xl border-2 cursor-pointer
75→        bg-gray-800/80 transition-all duration-75 select-none
76→        active:scale-90
77→        ${padColor}
78→        ${flash ? `${flashColor} scale-95` : ''}
79→      `}
80→    >
81→      <span className="text-xs sm:text-sm font-medium text-gray-200">{label}</span>
82→      <span className="text-[10px] text-gray-500 mt-0.5">{keyLabel}</span>
83→    </button>
84→  );
85→});
