 7→function getDotColor(absOffset: number): string {
 8→  if (absOffset < 15) return 'bg-green-400';
 9→  if (absOffset < 30) return 'bg-lime-400';
10→  if (absOffset < 50) return 'bg-yellow-400';
11→  return 'bg-orange-400';
12→}
