14→function TrackTimingRow({ instrumentId, label }: { instrumentId: InstrumentId; label: string }) {
15→  const data = useLivePracticeStore((s) => s.perTrackOffset[instrumentId]);
16→
17→  if (!data || data.grade === 'miss') {
18→    return (
19→      <div className="flex items-center gap-2">
20→        <span className="text-[10px] text-gray-600 w-14 truncate">{label}</span>
21→        <div className="relative flex-1 h-4">
22→          <div className="absolute inset-y-0 left-0 right-0 flex items-center">
23→            <div className="w-full h-0.5 bg-gray-800 rounded-full" />
24→          </div>
25→          <div className="absolute top-0 bottom-0 left-1/2 w-px bg-gray-700" />
26→        </div>
27→      </div>
28→    );
29→  }
30→
31→  const offsetMs = data.offset * 1000;
32→  const clamped = Math.max(-100, Math.min(100, offsetMs));
33→  const position = (clamped + 100) / 200;
34→  const dotColor = getDotColor(Math.abs(clamped));
35→  const offsetLabel = Math.round(offsetMs);
36→
37→  return (
38→    <div className="flex items-center gap-2">
