45→        <div
46→          className={`absolute top-1/2 w-2.5 h-2.5 rounded-full ${dotColor} transition-all duration-75`}
47→          style={{
48→            left: `${position * 100}%`,
49→            transform: 'translate(-50%, -50%)',
50→          }}
51→        />
52→      </div>
53→      <span className="text-[9px] text-gray-600 w-10 text-right tabular-nums">
54→        {offsetLabel > 0 ? '+' : ''}{offsetLabel}ms
55→      </span>
56→    </div>
57→  );
