### Feature 3: Friendly Feedback Messages

This feature analyzes the `detailedTaps` array (added in Shared Infrastructure C) and generates human-readable coaching insights.

#### Analysis Module

**New file:** `/Users/chiu.fyi/work/drum-practice/src/lib/live-practice/feedbackAnalyzer.ts`

```typescript
import { SessionStats, DetailedTapRecord } from './types';
import { InstrumentId } from '../patterns/types';

export interface FeedbackMessage {
  type: 'positive' | 'improvement' | 'suggestion';
  text: string;
  priority: number; // higher = show first
}

export function analyzeFeedback(
  stats: SessionStats,
  bpm: number,
  totalStepsPerBar: number
): FeedbackMessage[] {
  const messages: FeedbackMessage[] = [];
  const taps = stats.detailedTaps ?? [];

  if (taps.length < 4) return messages; // not enough data

  const accuracy = stats.totalExpected > 0
    ? (stats.totalHits / stats.totalExpected) * 100
    : 0;

  // 1. Overall accuracy-based suggestions
  if (accuracy >= 90) {
    messages.push({
      type: 'positive',
      text: `Clean at ${bpm} BPM -- ready to move up 5 BPM.`,
      priority: 10,
    });
  } else if (accuracy < 60) {
    const suggestedBpm = Math.max(40, bpm - 10);
    messages.push({
      type: 'suggestion',
      text: `Try dropping to ${suggestedBpm} BPM for cleaner practice.`,
      priority: 10,
    });
  }

  // 2. Per-step analysis: consistent lateness on specific beats
  analyzePerStepTiming(taps, totalStepsPerBar, messages);

  // 3. Per-instrument analysis: inconsistent instrument
  analyzePerInstrumentTiming(taps, messages);

  // 4. Rushing/dragging pattern (first half vs second half of bar)
  analyzeBarHalves(taps, totalStepsPerBar, messages);

  // Sort by priority descending, limit to top 3
  messages.sort((a, b) => b.priority - a.priority);
  return messages.slice(0, 3);
}

function analyzePerStepTiming(
  taps: DetailedTapRecord[],
  totalStepsPerBar: number,
  messages: FeedbackMessage[]
): void {
  // Group taps by step position
  const byStep = new Map<number, number[]>();
  for (const tap of taps) {
    const existing = byStep.get(tap.step) ?? [];
    existing.push(tap.offset);
    byStep.set(tap.step, existing);
  }

  for (const [step, offsets] of byStep) {
    if (offsets.length < 3) continue; // need enough samples
    const avgOffset = offsets.reduce((a, b) => a + b, 0) / offsets.length;
    const avgMs = avgOffset * 1000;

    // Consistently late (avg > 25ms late) or early (avg < -25ms)
    if (avgMs > 25) {
      // Convert step to beat number (1-indexed, approximate)
      const stepsPerBeat = totalStepsPerBar / 4; // assumes 4/4 for beat labeling
      const beatNum = Math.floor(step / stepsPerBeat) + 1;
      messages.push({
        type: 'improvement',
        text: `You're consistently late on beat ${beatNum}.`,
        priority: 7,
      });
    } else if (avgMs < -25) {
      const stepsPerBeat = totalStepsPerBar / 4;
      const beatNum = Math.floor(step / stepsPerBeat) + 1;
      messages.push({
        type: 'improvement',
        text: `You're rushing beat ${beatNum}.`,
        priority: 7,
      });
    }
  }
}

function analyzePerInstrumentTiming(
  taps: DetailedTapRecord[],
  messages: FeedbackMessage[]
): void {
  const byInstrument = new Map<InstrumentId, number[]>();
  for (const tap of taps) {
    const existing = byInstrument.get(tap.instrumentId) ?? [];
    existing.push(tap.offset);
    byInstrument.set(tap.instrumentId, existing);
  }

  // Calculate variance for each instrument
  const variances: { instrument: InstrumentId; variance: number; count: number }[] = [];
  for (const [instrument, offsets] of byInstrument) {
    if (offsets.length < 3) continue;
    const mean = offsets.reduce((a, b) => a + b, 0) / offsets.length;
    const variance = offsets.reduce((sum, o) => sum + (o - mean) ** 2, 0) / offsets.length;
    variances.push({ instrument, variance, count: offsets.length });
  }

  if (variances.length >= 2) {
    variances.sort((a, b) => b.variance - a.variance);
    const worst = variances[0];
    const best = variances[variances.length - 1];
    // Only report if the worst is significantly more inconsistent
    if (worst.variance > best.variance * 2) {
      const label = instrumentLabel(worst.instrument);
      messages.push({
        type: 'improvement',
        text: `Your ${label} timing is the most inconsistent.`,
        priority: 6,
      });
    }
  }
}

function analyzeBarHalves(
  taps: DetailedTapRecord[],
  totalStepsPerBar: number,
  messages: FeedbackMessage[]
): void {
  const halfwayStep = totalStepsPerBar / 2;
  const firstHalf: number[] = [];
  const secondHalf: number[] = [];

  for (const tap of taps) {
    if (tap.step < halfwayStep) {
      firstHalf.push(tap.offset);
    } else {
      secondHalf.push(tap.offset);
    }
  }

  if (firstHalf.length < 3 || secondHalf.length < 3) return;

  const avgFirst = firstHalf.reduce((a, b) => a + b, 0) / firstHalf.length * 1000;
  const avgSecond = secondHalf.reduce((a, b) => a + b, 0) / secondHalf.length * 1000;

  // If second half is significantly earlier than first half -> rushing
  if (avgSecond < avgFirst - 15 && avgSecond < -10) {
    messages.push({
      type: 'improvement',
      text: 'Rushing during the second half of each bar.',
      priority: 8,
    });
  }
  // If second half is significantly later -> dragging
  if (avgSecond > avgFirst + 15 && avgSecond > 10) {
    messages.push({
      type: 'improvement',
      text: 'Dragging during the second half of each bar.',
      priority: 8,
    });
  }
}

function instrumentLabel(id: InstrumentId): string {
  const labels: Record<InstrumentId, string> = {
    kick: 'kick',
    snare: 'snare',
    'hihat-closed': 'hi-hat',
    'hihat-open': 'open hi-hat',
    'tom-high': 'high tom',
    'tom-mid': 'mid tom',
    'tom-low': 'floor tom',
    crash: 'crash',
    ride: 'ride',
  };
  return labels[id] ?? id;
}
```

