  floorBarIndex: number;    // which bar the drop was detected
  floorAccuracy: number;    // accuracy at the floor
}

/**
 * Analyze bar history to find the BPM where accuracy drops significantly.
 *
 * Strategy:
 * 1. Look at bars that have BPM data.
 * 2. Group consecutive bars by BPM.
 * 3. For each BPM group, compute average accuracy.
 * 4. Find the first BPM where average accuracy drops below threshold (70%).
 * 5. If no clear cliff, find where accuracy first dips below 80%.
 * 6. Recommend 5 BPM below the floor.
 */
export function findTempoFloor(
  barHistory: BarAccuracy[],
  accuracyThreshold: number = 70
): TempoFloorResult | null {
  // Filter bars that have BPM data
  const barsWithBpm = barHistory.filter((b) => b.bpm !== undefined && b.bpm !== null);
  if (barsWithBpm.length < 4) return null;

  // Group by BPM, preserving order
  const groups: { bpm: number; accuracies: number[]; firstBarIndex: number }[] = [];
  let currentGroup: typeof groups[0] | null = null;

  for (let i = 0; i < barsWithBpm.length; i++) {
    const bar = barsWithBpm[i];
    if (!currentGroup || currentGroup.bpm !== bar.bpm!) {
      currentGroup = { bpm: bar.bpm!, accuracies: [], firstBarIndex: i };
      groups.push(currentGroup);
    }
    currentGroup.accuracies.push(bar.accuracy);
  }

  // Calculate average accuracy per BPM group
  const bpmAccuracies = groups.map((g) => ({
    bpm: g.bpm,
    avgAccuracy: g.accuracies.reduce((a, b) => a + b, 0) / g.accuracies.length,
    firstBarIndex: g.firstBarIndex,
  }));

  // Find the first group that drops below threshold
  for (let i = 0; i < bpmAccuracies.length; i++) {
    if (bpmAccuracies[i].avgAccuracy < accuracyThreshold) {
      return {
        tempoFloor: bpmAccuracies[i].bpm,
        recommendedBpm: Math.max(40, bpmAccuracies[i].bpm - 5),
        floorBarIndex: bpmAccuracies[i].firstBarIndex,
        floorAccuracy: Math.round(bpmAccuracies[i].avgAccuracy),
      };
    }
  }

  // No clear cliff -- check for sub-80% dip
  for (let i = 0; i < bpmAccuracies.length; i++) {
    if (bpmAccuracies[i].avgAccuracy < 80) {
      return {
        tempoFloor: bpmAccuracies[i].bpm,
        recommendedBpm: Math.max(40, bpmAccuracies[i].bpm - 5),
        floorBarIndex: bpmAccuracies[i].firstBarIndex,
        floorAccuracy: Math.round(bpmAccuracies[i].avgAccuracy),
      };
    }
  }

  return null; // Accuracy stayed high throughout -- no floor found
}
```

