#### New Audio Module: MetronomeClick

**New file:** `/Users/chiu.fyi/work/drum-practice/src/lib/audio/MetronomeClick.ts`

This module synthesizes a simple click sound using a sine wave oscillator (like the existing DrumSynth pattern):

```typescript
import { audioEngine } from './AudioEngine';

/**
 * Play a metronome click.
 * @param time - AudioContext time to schedule the click
 * @param isDownbeat - true for beat 1 (higher pitch)
 * @param volume - 0.0 to 1.0
 */
export function playMetronomeClick(
  time: number,
  isDownbeat: boolean,
  volume: number
): void {
  const ctx = audioEngine.context;
  if (!ctx) return;
  const dest = audioEngine.destination;

  const osc = ctx.createOscillator();
  osc.type = 'sine';
  // Higher pitch for downbeat (1000Hz), normal for others (800Hz)
  osc.frequency.setValueAtTime(isDownbeat ? 1000 : 800, time);

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(volume * 0.5, time);
  gain.gain.exponentialRampToValueAtTime(0.001, time + 0.05);

  osc.connect(gain).connect(dest);
  osc.start(time);
  osc.stop(time + 0.05);
}
```

Design notes: Using a short 50ms sine click matches the existing pattern of oscillator-based synthesis in DrumSynth. The downbeat is 1000Hz (a clear "tick") and other beats are 800Hz (a softer "tock"). Volume multiplied by 0.5 to keep it from overpowering drum sounds.

