  1→import { create } from 'zustand';
  2→import { persist } from 'zustand/middleware';
  3→import { SessionStats } from '../live-practice/types';
  4→import {
  5→  SpacedRepCard,
  6→  accuracyToQuality,
  7→  computeNextReview,
  8→  isCardDue,
  9→} from '../spaced-repetition/sm2';
 10→import { allPatterns } from '../patterns';
 11→
 12→export type PracticeSessionMode = 'loop' | 'tempo-ramp' | 'live';
 13→
 14→export interface PracticeSession {
 15→  id: string;
 16→  patternId: string;
 17→  patternName: string;
 18→  mode: PracticeSessionMode;
 19→  startedAt: number;
 20→  endedAt: number;
 21→  durationMs: number;
 22→  bpm: number;
 23→  bpmStart?: number;
 24→  bpmEnd?: number;
 25→  accuracy: number | null;
 26→  stats: SessionStats | null;
 27→}
 28→
 29→const MAX_SESSIONS = 2000;
 30→
 31→interface PracticeHistoryState {
 32→  sessions: PracticeSession[];
 33→  cards: Record<string, SpacedRepCard>;
 34→
 35→  addSession: (session: Omit<PracticeSession, 'id'>) => void;
 36→  updateCard: (patternId: string, accuracy: number) => void;
 37→  clearHistory: () => void;
 38→}
 39→
 40→export const usePracticeHistoryStore = create<PracticeHistoryState>()(
 41→  persist(
 42→    (set, get) => ({
 43→      sessions: [],
 44→      cards: {},
 45→
 46→      addSession: (sessionData) => {
 47→        const session: PracticeSession = {
 48→          ...sessionData,
 49→          id: crypto.randomUUID(),
 50→        };
 51→        set((state) => ({
 52→          sessions: [session, ...state.sessions].slice(0, MAX_SESSIONS),
 53→        }));
 54→      },
 55→
 56→      updateCard: (patternId, accuracy) => {
 57→        const existing = get().cards[patternId];
 58→        const current = existing ?? {
 59→          easeFactor: 2.5,
 60→          intervalDays: 1,
 61→          repetitions: 0,
 62→        };
 63→        const quality = accuracyToQuality(accuracy);
 64→        const result = computeNextReview(current, quality);
 65→
 66→        set((state) => ({
 67→          cards: {
 68→            ...state.cards,
 69→            [patternId]: {
 70→              patternId,
 71→              easeFactor: result.easeFactor,
 72→              intervalDays: result.intervalDays,
 73→              repetitions: result.repetitions,
 74→              lastReviewedAt: Date.now(),
 75→              nextReviewAt: result.nextReviewAt,
 76→              lastAccuracy: accuracy,
 77→            },
 78→          },
 79→        }));
 80→      },
 81→
 82→      clearHistory: () => set({ sessions: [], cards: {} }),
 83→    }),
 84→    {
 85→      name: 'drum-practice-history',
 86→      partialize: (state) => ({
 87→        sessions: state.sessions,
 88→        cards: state.cards,
 89→      }),
 90→    }
 91→  )
 92→);
 93→
 94→// Selector helpers (use outside React or in callbacks)
 95→
 96→export function getSessionsForPattern(patternId: string): PracticeSession[] {
 97→  return usePracticeHistoryStore
 98→    .getState()
 99→    .sessions.filter((s) => s.patternId === patternId);
100→}
101→
102→export function getLastLiveSessionForPattern(patternId: string): PracticeSession | null {
