 46→
 47→  const [showResults, setShowResults] = useState(false);
 48→
 49→  const tapMatcherRef = useRef<TapMatcher | null>(null);
 50→  const sweepIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
 51→  const sessionStartRef = useRef<number>(0);
 52→
 53→  // Initialize TapMatcher
 54→  if (!tapMatcherRef.current) {
 55→    tapMatcherRef.current = new TapMatcher();
 56→  }
 57→
 58→  // Convert stepAccuracies to the format BeatGrid expects: Record<string, TimingGrade>
 59→  const stepAccuracies = useMemo(() => {
 60→    const result: Record<string, TimingGrade> = {};
 61→    for (const [key, acc] of Object.entries(stepAccuraciesRaw)) {
 62→      result[key] = acc.grade;
 63→    }
 64→    return result;
 65→  }, [stepAccuraciesRaw]);
 66→
 67→  // Register step listener for feeding expected beats to TapMatcher
 68→  useEffect(() => {
 69→    const unsubscribe = scheduler.addStepListener((step, time) => {
 70→      const tapMatcher = tapMatcherRef.current;
 71→      if (!tapMatcher || !useLivePracticeStore.getState().isActive) return;
