 1→import { audioEngine } from './AudioEngine';
 2→import { ALL_NOTES } from '../sight-reading/notes';
 3→
 4→/**
 5→ * Play a piano-like tone using layered sine oscillators.
 6→ * Layers: fundamental + 2nd harmonic (0.4x) + 3rd harmonic (0.15x)
 7→ * with an exponential decay envelope.
 8→ */
 9→export function playPianoNote(
10→  noteIndex: number,
11→  velocity: number = 0.6
12→): void {
13→  const ctx = audioEngine.context;
14→  if (!ctx) return;
15→
16→  const note = ALL_NOTES[noteIndex];
17→  if (!note) return;
18→
19→  const dest = audioEngine.destination;
20→  const time = ctx.currentTime;
21→  const freq = note.frequency;
22→  const duration = 1.5;
23→
24→  // Harmonics: [multiplier, amplitude ratio]
25→  const harmonics: [number, number][] = [
26→    [1, 1.0],    // fundamental
27→    [2, 0.4],    // 2nd harmonic
28→    [3, 0.15],   // 3rd harmonic
29→  ];
30→
31→  // Shared gain envelope for all harmonics
32→  const gainNode = ctx.createGain();
33→  gainNode.gain.setValueAtTime(velocity * 0.5, time);
34→  gainNode.gain.exponentialRampToValueAtTime(0.001, time + duration);
35→  gainNode.connect(dest);
36→
37→  for (const [mult, amp] of harmonics) {
38→    const osc = ctx.createOscillator();
39→    osc.type = 'sine';
40→    osc.frequency.setValueAtTime(freq * mult, time);
41→
42→    const harmGain = ctx.createGain();
43→    harmGain.gain.setValueAtTime(amp, time);
44→
45→    osc.connect(harmGain).connect(gainNode);
46→    osc.start(time);
47→    osc.stop(time + duration);
48→  }
49→}
50→
51→/**
52→ * Play a short error buzz — filtered noise burst to indicate wrong note.
53→ */
54→export function playErrorBuzz(): void {
55→  const ctx = audioEngine.context;
56→  if (!ctx) return;
57→
58→  const noiseBuffer = audioEngine.noiseBuffer;
59→  if (!noiseBuffer) return;
60→
61→  const dest = audioEngine.destination;
62→  const time = ctx.currentTime;
63→
64→  const source = ctx.createBufferSource();
65→  source.buffer = noiseBuffer;
66→
67→  const filter = ctx.createBiquadFilter();
68→  filter.type = 'bandpass';
69→  filter.frequency.setValueAtTime(800, time);
70→  filter.Q.setValueAtTime(2, time);
71→
72→  const gain = ctx.createGain();
73→  gain.gain.setValueAtTime(0.15, time);
74→  gain.gain.exponentialRampToValueAtTime(0.001, time + 0.12);
75→
76→  source.connect(filter).connect(gain).connect(dest);
77→  source.start(time);
78→  source.stop(time + 0.12);
79→}
