 24→  const startSession = useSightReadingStore((s) => s.startSession);
 25→  const nextChallenge = useSightReadingStore((s) => s.nextChallenge);
 26→  const submitNote = useSightReadingStore((s) => s.submitNote);
 27→  const resetSession = useSightReadingStore((s) => s.resetSession);
 28→
 29→  const [activeNote, setActiveNote] = useState<number | null>(null);
 30→  const activeNoteTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
 31→  const autoAdvanceTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
 32→
 33→  // Clear timeouts on unmount
 34→  useEffect(() => {
 35→    return () => {
 36→      if (activeNoteTimeout.current) clearTimeout(activeNoteTimeout.current);
 37→      if (autoAdvanceTimeout.current) clearTimeout(autoAdvanceTimeout.current);
 38→    };
 39→  }, []);
 40→
 41→  const handleNotePlay = useCallback(
 42→    (noteIndex: number) => {
 43→      // Ensure audio context is initialized
 44→      audioEngine.init();
 45→
 46→      // Visual feedback — flash the key
 47→      setActiveNote(noteIndex);
 48→      if (activeNoteTimeout.current) clearTimeout(activeNoteTimeout.current);
 49→      activeNoteTimeout.current = setTimeout(() => setActiveNote(null), 200);
 50→
 51→      // If no active challenge, just play the sound
 52→      if (!challengeActive) {
 53→        playPianoNote(noteIndex);
 54→        return;
 55→      }
 56→
 57→      // Get current state directly to avoid stale closures
 58→      const state = useSightReadingStore.getState();
 59→      const targetNote = state.targetNotes[state.currentNoteIndex];
 60→      const correct = noteIndex === targetNote;
 61→
 62→      if (correct) {
 63→        playPianoNote(noteIndex);
 64→      } else {
 65→        playPianoNote(noteIndex, 0.3); // play wrong note quietly
 66→        playErrorBuzz();
 67→      }
 68→
 69→      submitNote(noteIndex);
 70→
 71→      // Auto-advance after completing a challenge
 72→      const updatedState = useSightReadingStore.getState();
 73→      if (!updatedState.challengeActive) {
 74→        if (autoAdvanceTimeout.current) clearTimeout(autoAdvanceTimeout.current);
 75→        autoAdvanceTimeout.current = setTimeout(() => {
 76→          nextChallenge();
 77→        }, 1200);
 78→      }
 79→    },
 80→    [challengeActive, submitNote, nextChallenge]
 81→  );
 82→
 83→  // Keyboard input
 84→  usePianoKeyboard(handleNotePlay, true);
 85→
 86→  const handleStart = useCallback(() => {
 87→    audioEngine.init();
 88→    startSession();
 89→  }, [startSession]);
 90→
 91→  const handleReset = useCallback(() => {
 92→    if (autoAdvanceTimeout.current) clearTimeout(autoAdvanceTimeout.current);
 93→    resetSession();
 94→  }, [resetSession]);
 95→
 96→  // Build results array for staff coloring
 97→  const staffResults = results.map((r) => ({ correct: r.correct }));
 98→
 99→  const hasSession = stats.startTime !== null;
100→
101→  return (
102→    <div className="min-h-screen">
103→      <Header />
104→      <main className="max-w-5xl mx-auto px-4 py-6">
105→        {/* Title + mode/difficulty selectors */}
106→        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-6">
107→          <div>
108→            <h1 className="text-xl font-bold mb-1">Sight Reading</h1>
109→            <p className="text-sm text-gray-500">
110→              Read notes on the staff and play them on the piano
111→            </p>
112→          </div>
113→          <div className="flex flex-col sm:flex-row gap-2">
114→            <SightReadingModeSelector />
115→            <DifficultySelector />
116→          </div>
117→        </div>
118→
119→        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
120→          {/* Main area: staff + feedback + piano */}
121→          <div className="md:col-span-2 flex flex-col gap-4">
122→            {/* Staff */}
123→            <div className="bg-[#1a1d27] rounded-xl p-6 border border-gray-800 flex flex-col items-center">
124→              {targetNotes.length > 0 ? (
125→                <Staff
126→                  noteIndices={targetNotes}
127→                  currentNoteIndex={currentNoteIndex}
128→                  results={staffResults}
129→                />
130→              ) : (
131→                <div className="flex flex-col items-center justify-center h-40 text-gray-500">
132→                  <p className="text-sm mb-4">
133→                    {mode === 'note-drill' && 'Identify notes as they appear on the staff'}
134→                    {mode === 'interval' && 'Play two-note intervals in order'}
135→                    {mode === 'phrase' && 'Read and play short melodies'}
136→                  </p>
137→                  <button
138→                    onClick={handleStart}
139→                    className="px-6 py-2.5 bg-white text-gray-900 rounded-lg font-medium
140→                               hover:bg-gray-200 transition-colors cursor-pointer"
141→                  >
142→                    Start Practice
143→                  </button>
144→                </div>
145→              )}
146→
147→              {/* Result feedback */}
148→              <ResultFeedback />
149→
150→              {/* Controls */}
151→              {hasSession && (
152→                <div className="flex gap-3 mt-2">
153→                  {!challengeActive && targetNotes.length > 0 && (
154→                    <button
155→                      onClick={nextChallenge}
156→                      className="px-4 py-1.5 bg-white text-gray-900 rounded-lg text-sm font-medium
157→                                 hover:bg-gray-200 transition-colors cursor-pointer"
158→                    >
159→                      Next
160→                    </button>
161→                  )}
162→                  <button
163→                    onClick={handleReset}
164→                    className="px-4 py-1.5 bg-gray-800 text-gray-300 rounded-lg text-sm font-medium
165→                               hover:bg-gray-700 transition-colors cursor-pointer"
166→                  >
167→                    Reset
168→                  </button>
169→                </div>
170→              )}
171→            </div>
172→
173→            {/* Piano */}
174→            <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
175→              <PianoKeyboard onNotePlay={handleNotePlay} activeNote={activeNote} />
176→            </div>
177→
178→            {/* Note name hint for current target */}
179→            {challengeActive && targetNotes.length > 0 && (
180→              <div className="text-center text-xs text-gray-600">
181→                Target: {ALL_NOTES[targetNotes[currentNoteIndex]]?.name}
182→                <span className="ml-2 text-gray-700">(shown on staff above)</span>
183→              </div>
184→            )}
185→          </div>
186→
187→          {/* Sidebar: Stats */}
188→          <div className="flex flex-col gap-4">
189→            <StatsPanel />
190→
191→            {/* Keyboard help */}
192→            <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
193→              <h3 className="text-sm font-medium text-gray-400 mb-2">Keyboard</h3>
194→              <div className="text-xs text-gray-500 space-y-1">
195→                <p>
196→                  <span className="text-gray-400">Lower octave:</span>{' '}
197→                  <kbd className="bg-gray-800 px-1 rounded">Z</kbd>-
198→                  <kbd className="bg-gray-800 px-1 rounded">M</kbd> = C3-B3
199→                </p>
200→                <p>
201→                  <span className="text-gray-400">Upper octave:</span>{' '}
202→                  <kbd className="bg-gray-800 px-1 rounded">Q</kbd>-
203→                  <kbd className="bg-gray-800 px-1 rounded">U</kbd> = C4-B4
204→                </p>
205→                <p className="text-gray-600 mt-2">
206→                  White keys on letter rows, black keys on the row above
207→                </p>
208→              </div>
209→            </div>
210→          </div>
211→        </div>
212→      </main>
213→    </div>
214→  );
215→}
