 29→export default function LivePracticePage() {
 30→  const pattern = usePatternStore((s) => s.currentPattern);
 31→  const playState = useTransportStore((s) => s.playState);
 32→  const play = useTransportStore((s) => s.play);
 33→  const stop = useTransportStore((s) => s.stop);
 34→  const bpm = useTransportStore((s) => s.bpm);
 35→
 36→  const isActive = useLivePracticeStore((s) => s.isActive);
 37→  const startSession = useLivePracticeStore((s) => s.startSession);
 38→  const endSession = useLivePracticeStore((s) => s.endSession);
 39→  const mode = useLivePracticeStore((s) => s.mode);
 40→  const focusedTrack = useLivePracticeStore((s) => s.focusedTrack);
 41→  const stepAccuraciesRaw = useLivePracticeStore((s) => s.stepAccuracies);
 42→  const recordMiss = useLivePracticeStore((s) => s.recordMiss);
 43→  const resetStepAccuracies = useLivePracticeStore((s) => s.resetStepAccuracies);
 44→  const stats = useLivePracticeStore((s) => s.stats);
 45→
 46→  const addHistorySession = usePracticeHistoryStore((s) => s.addSession);
 47→  const updateCard = usePracticeHistoryStore((s) => s.updateCard);
 48→
 49→  const [showResults, setShowResults] = useState(false);
 50→
 51→  const tapMatcherRef = useRef<TapMatcher | null>(null);
 52→  const sweepIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
 53→  const sessionStartRef = useRef<number>(0);
 54→
 55→  // Initialize TapMatcher
 56→  if (!tapMatcherRef.current) {
 57→    tapMatcherRef.current = new TapMatcher();
 58→  }
 59→
 60→  // Convert stepAccuracies to the format BeatGrid expects: Record<string, TimingGrade>
 61→  const stepAccuracies = useMemo(() => {
 62→    const result: Record<string, TimingGrade> = {};
 63→    for (const [key, acc] of Object.entries(stepAccuraciesRaw)) {
 64→      result[key] = acc.grade;
 65→    }
 66→    return result;
 67→  }, [stepAccuraciesRaw]);
 68→
 69→  // Register step listener for feeding expected beats to TapMatcher
 70→  useEffect(() => {
 71→    const unsubscribe = scheduler.addStepListener((step, time) => {
 72→      const tapMatcher = tapMatcherRef.current;
 73→      if (!tapMatcher || !useLivePracticeStore.getState().isActive) return;
 74→
 75→      const liveMode = useLivePracticeStore.getState().mode;
 76→      const focused = useLivePracticeStore.getState().focusedTrack;
 77→      const currentPattern = usePatternStore.getState().currentPattern;
 78→
 79→      currentPattern.tracks.forEach((track: Track) => {
 80→        const s = track.steps[step];
 81→        if (!s || !s.active) return;
 82→
 83→        // In single-track mode, only expect beats for the focused instrument
 84→        if (liveMode === 'single-track' && focused && track.instrumentId !== focused) return;
 85→
 86→        tapMatcher.addExpectedBeat(step, time, track.instrumentId);
 87→      });
 88→    });
 89→
 90→    return unsubscribe;
 91→  }, []);
 92→
 93→  // Sweep for misses periodically
 94→  useEffect(() => {
 95→    if (isActive) {
 96→      sweepIntervalRef.current = setInterval(() => {
 97→        const tapMatcher = tapMatcherRef.current;
 98→        if (!tapMatcher) return;
 99→        const misses = tapMatcher.sweepMisses(audioEngine.currentTime);
100→        misses.forEach((miss) => {
101→          recordMiss(miss.step, miss.instrumentId);
102→        });
103→      }, 50);
104→    } else {
105→      if (sweepIntervalRef.current) {
106→        clearInterval(sweepIntervalRef.current);
107→      }
108→    }
109→
110→    return () => {
111→      if (sweepIntervalRef.current) {
112→        clearInterval(sweepIntervalRef.current);
113→      }
114→    };
115→  }, [isActive, recordMiss]);
116→
117→  // Record bar accuracy + reset step accuracy display each bar
118→  useEffect(() => {
119→    const unsubscribe = scheduler.addStepListener((step) => {
120→      if (step === 0 && useLivePracticeStore.getState().isActive) {
121→        const currentBpm = useTransportStore.getState().bpm;
122→        useLivePracticeStore.getState().recordBarEnd(currentBpm);
123→        useLivePracticeStore.getState().resetStepAccuracies();
124→      }
125→    });
126→    return unsubscribe;
127→  }, []);
128→
129→  // Handle keyboard taps
130→  useLiveKeyboardHandler(tapMatcherRef.current, isActive);
131→
132→  // Handle play/stop with session tracking
133→  const handlePlay = useCallback(() => {
134→    tapMatcherRef.current?.reset();
135→    sessionStartRef.current = Date.now();
136→    startSession();
137→    resetStepAccuracies();
138→    play();
139→  }, [play, startSession, resetStepAccuracies]);
140→
141→  const handleStop = useCallback(() => {
142→    const sessionEndTime = Date.now();
143→    stop();
144→    // Final sweep for any remaining expected beats
145→    if (tapMatcherRef.current) {
146→      const misses = tapMatcherRef.current.sweepMisses(Infinity);
147→      const rm = useLivePracticeStore.getState().recordMiss;
148→      misses.forEach((miss) => rm(miss.step, miss.instrumentId));
149→    }
150→    endSession();
151→
152→    // Persist session to history
153→    const finalStats = useLivePracticeStore.getState().stats;
154→    const currentPattern = usePatternStore.getState().currentPattern;
155→    const currentBpm = useTransportStore.getState().bpm;
156→    const drillDurationMs = useLivePracticeStore.getState().drillDurationMs;
157→    const durationMs = sessionEndTime - sessionStartRef.current;
158→
159→    if (finalStats.totalExpected > 0 && durationMs > 5000) {
160→      const accuracy = Math.round(
161→        (finalStats.totalHits / finalStats.totalExpected) * 100
162→      );
163→      const tempoFloorResult = findTempoFloor(finalStats.barHistory);
164→      addHistorySession({
165→        patternId: currentPattern.id,
166→        patternName: currentPattern.name,
167→        mode: 'live',
168→        startedAt: sessionStartRef.current,
169→        endedAt: sessionEndTime,
170→        durationMs,
171→        bpm: currentBpm,
172→        accuracy,
173→        stats: { ...finalStats, detailedTaps: [] },
174→        drillDurationMs: drillDurationMs ?? undefined,
175→        tempoFloor: tempoFloorResult?.recommendedBpm,
176→      });
177→      updateCard(currentPattern.id, accuracy);
178→      setShowResults(true);
179→    }
180→  }, [stop, endSession, addHistorySession, updateCard]);
181→
182→  // Auto-stop when drill timer expires
183→  useDrillTimer(handleStop);
184→
185→  const handleRetry = useCallback(() => {
186→    setShowResults(false);
187→    handlePlay();
188→  }, [handlePlay]);
189→
190→  const router = useRouter();
191→  const handleBackToPatterns = useCallback(() => {
192→    setShowResults(false);
193→    router.push('/');
194→  }, [router]);
195→
196→  return (
197→    <div className="min-h-screen">
198→      <Header />
199→      <main className="max-w-5xl mx-auto px-4 py-6">
200→        {/* Pattern info + mode */}
201→        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-4">
202→          <div>
203→            <div className="flex items-center gap-3 mb-1">
204→              <h1 className="text-xl font-bold">{pattern.name}</h1>
205→              <span className="text-xs bg-gray-800 text-gray-400 px-2 py-0.5 rounded-full">
206→                {pattern.timeSignature.beats}/{pattern.timeSignature.noteValue}
207→              </span>
208→              <span className="text-xs bg-gray-800 text-gray-400 px-2 py-0.5 rounded-full">
209→                {pattern.subdivision}
210→              </span>
211→            </div>
212→            <p className="text-sm text-gray-500">{pattern.description}</p>
213→          </div>
214→          <ModeSelector />
215→        </div>
216→
217→        {/* Beat grid with accuracy overlay */}
218→        <div className="mb-2 overflow-x-auto">
219→          <BeatGrid stepAccuracies={isActive || stats.totalExpected > 0 ? stepAccuracies : undefined} />
220→        </div>
221→
222→        {/* Bar history strip */}
223→        <div className="mb-4">
224→          <BarHistoryStrip />
225→        </div>
226→
227→        {/* Timing + streak */}
228→        <div className="mb-4 space-y-2">
229→          <TimingIndicator />
230→          <StreakDisplay />
231→        </div>
232→
233→        {/* Controls + pads + stats */}
234→        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
235→          {/* Transport + BPM + Metronome + Drill */}
236→          <div className="flex flex-col gap-4">
237→            <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
238→              <div className="flex items-center gap-3 mb-4">
239→                {/* Custom play/stop that manages sessions */}
240→                <button
241→                  onClick={playState === 'playing' ? handleStop : handlePlay}
242→                  className="w-14 h-14 rounded-full bg-white text-gray-900 flex items-center justify-center
243→                             hover:bg-gray-200 active:scale-95 transition-all cursor-pointer shadow-lg"
244→                  aria-label={playState === 'playing' ? 'Stop' : 'Start'}
245→                >
246→                  {playState === 'playing' ? (
247→                    <svg width="14" height="14" viewBox="0 0 14 14" fill="currentColor">
248→                      <rect x="1" y="1" width="12" height="12" rx="2" />
249→                    </svg>
250→                  ) : (
251→                    <svg width="20" height="20" viewBox="0 0 20 20" fill="currentColor">
252→                      <path d="M5 3.5L16.5 10L5 16.5V3.5Z" />
253→                    </svg>
254→                  )}
255→                </button>
256→                {isActive && (
257→                  <div className="flex items-center gap-1.5">
258→                    <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
259→                    <span className="text-xs text-gray-400 uppercase tracking-wider">Live</span>
260→                  </div>
261→                )}
262→                <DrillCountdown />
263→              </div>
264→              <BpmControl />
265→              <div className="mt-3 pt-3 border-t border-gray-800">
266→                <MetronomeControls />
267→              </div>
268→              <div className="mt-3 pt-3 border-t border-gray-800">
269→                <DrillTimerSelector />
270→              </div>
271→            </div>
272→          </div>
273→
274→          {/* Tap pads */}
275→          <TapPadPanel tapMatcher={tapMatcherRef.current} isActive={isActive} />
276→
277→          {/* Stats */}
278→          <LiveStatsPanel />
279→        </div>
280→
281→        {/* Help text */}
282→        <div className="mt-4 text-center text-xs text-gray-600">
283→          Press the mapped keys to tap along with the beat.
284→          <span className="mx-2">|</span>
285→          <span className="bg-gray-800/50 px-2 py-1 rounded">D</span> Kick
286→          <span className="mx-1">|</span>
287→          <span className="bg-gray-800/50 px-2 py-1 rounded">F</span> Snare
288→          <span className="mx-1">|</span>
289→          <span className="bg-gray-800/50 px-2 py-1 rounded">J</span> Hi-Hat
290→        </div>
291→      </main>
292→
293→      {/* Results modal */}
294→      <LiveResultsModal
295→        isOpen={showResults}
296→        onRetry={handleRetry}
297→        onClose={handleBackToPatterns}
298→      />
299→    </div>
300→  );
301→}
