 66→  lastResult: null,
 67→
 68→  stats: { ...initialStats },
 69→
 70→  setMode: (mode) => {
 71→    set({ mode, targetNotes: [], currentNoteIndex: 0, challengeActive: false, lastResult: null });
 72→  },
 73→
 74→  setDifficulty: (difficulty) => {
 75→    set({ difficulty, targetNotes: [], currentNoteIndex: 0, challengeActive: false, lastResult: null });
 76→  },
 77→
 78→  startSession: () => {
 79→    const { mode, difficulty } = get();
 80→    const targetNotes = generateChallenge(mode, difficulty);
 81→    set({
 82→      targetNotes,
 83→      currentNoteIndex: 0,
 84→      challengeActive: true,
 85→      challengeStartTime: Date.now(),
 86→      results: [],
 87→      lastResult: null,
 88→      stats: { ...initialStats, startTime: Date.now() },
 89→    });
 90→  },
 91→
 92→  nextChallenge: () => {
 93→    const { mode, difficulty, targetNotes } = get();
 94→    const previousNote = targetNotes.length > 0 ? targetNotes[targetNotes.length - 1] : undefined;
 95→    const newTargetNotes = generateChallenge(mode, difficulty, previousNote);
 96→    set({
 97→      targetNotes: newTargetNotes,
 98→      currentNoteIndex: 0,
 99→      challengeActive: true,
100→      challengeStartTime: Date.now(),
101→      lastResult: null,
102→    });
103→  },
104→
105→  submitNote: (noteIndex) => {
106→    const state = get();
107→    if (!state.challengeActive) return;
108→
109→    const targetNote = state.targetNotes[state.currentNoteIndex];
110→    if (targetNote === undefined) return;
111→
112→    const correct = noteIndex === targetNote;
113→    const responseTimeMs = state.challengeStartTime
114→      ? Date.now() - state.challengeStartTime
115→      : 0;
116→
117→    const result: NoteResult = {
118→      targetNote,
119→      playedNote: noteIndex,
120→      correct,
121→      responseTimeMs,
122→    };
123→
124→    const newResults = [...state.results, result];
125→    const newTotal = state.stats.totalAttempts + 1;
126→    const newCorrect = state.stats.correct + (correct ? 1 : 0);
127→    const newStreak = correct ? state.stats.streak + 1 : 0;
128→    const newBestStreak = Math.max(state.stats.bestStreak, newStreak);
129→
130→    // Running average response time (only for correct answers)
131→    let newAvgMs = state.stats.avgResponseMs;
132→    if (correct) {
133→      const prevCorrectCount = state.stats.correct;
134→      newAvgMs =
135→        prevCorrectCount === 0
136→          ? responseTimeMs
137→          : (state.stats.avgResponseMs * prevCorrectCount + responseTimeMs) /
138→            (prevCorrectCount + 1);
139→    }
140→
141→    const nextIndex = state.currentNoteIndex + 1;
142→    const challengeComplete = nextIndex >= state.targetNotes.length;
143→
144→    set({
145→      results: newResults,
146→      lastResult: correct ? 'correct' : 'wrong',
147→      currentNoteIndex: challengeComplete ? state.currentNoteIndex : nextIndex,
148→      challengeActive: !challengeComplete,
149→      challengeStartTime: challengeComplete ? null : Date.now(),
150→      stats: {
151→        ...state.stats,
152→        totalAttempts: newTotal,
153→        correct: newCorrect,
154→        streak: newStreak,
155→        bestStreak: newBestStreak,
156→        avgResponseMs: newAvgMs,
157→      },
158→    });
159→  },
160→
161→  resetSession: () => {
162→    set({
163→      targetNotes: [],
164→      currentNoteIndex: 0,
165→      challengeActive: false,
166→      challengeStartTime: null,
167→      results: [],
168→      lastResult: null,
169→      stats: { ...initialStats },
170→    });
171→  },
172→}));
