  7→interface StaffProps {
  8→  noteIndices: number[];
  9→  currentNoteIndex: number;
 10→  results?: { correct: boolean }[];
 11→}
 12→
 13→// Staff dimensions
 14→const STAFF_WIDTH = 600;
 15→const STAFF_HEIGHT = 260;
 16→const STAFF_TOP = 60;       // Y of top staff line
 17→const LINE_SPACING = 14;    // pixels between staff lines
 18→const LEFT_MARGIN = 80;     // space for clef
 19→const NOTE_SPACING = 70;    // horizontal spacing between notes
 20→
 21→// Staff line positions (5 lines, top to bottom)
 22→// Treble clef lines from top: F5, D5, B4, G4, E4
 23→const STAFF_LINES = [0, 1, 2, 3, 4].map((i) => STAFF_TOP + i * LINE_SPACING);
 24→
 25→// Map staffSlot to Y position
 26→// staffSlot: diatonic steps from C4.
 27→// E4 (staffSlot=2) is on the bottom staff line (STAFF_LINES[4])
 28→// Each diatonic step = LINE_SPACING / 2
 29→function staffSlotToY(staffSlot: number): number {
 30→  // E4 has staffSlot = 2, sits on STAFF_LINES[4]
 31→  // Each step up = LINE_SPACING/2 pixels up
 32→  const e4Y = STAFF_LINES[4]; // bottom line
 33→  return e4Y - (staffSlot - 2) * (LINE_SPACING / 2);
 34→}
 35→
 36→// Determine which ledger lines are needed for a note
 37→function getLedgerLines(staffSlot: number): number[] {
 38→  const lines: number[] = [];
 39→
 40→  // Ledger lines below staff (below E4, staffSlot < 2)
 41→  // Middle C (C4, staffSlot=0) needs one ledger line
 42→  // B3 (staffSlot=-1) sits just below that ledger line (no extra)
 43→  // A3 (staffSlot=-2) needs the C ledger line
 44→  // etc.
 45→  if (staffSlot <= 0) {
 46→    // Need ledger lines at staffSlot 0 (C4), -2 (A3), -4 (F3), -6 (D3)
 47→    for (let s = 0; s >= staffSlot; s -= 2) {
 48→      lines.push(s);
 49→    }
 50→  }
 51→
 52→  // Ledger lines above staff (above F5, staffSlot > 10)
 53→  if (staffSlot >= 12) {
 54→    for (let s = 12; s <= staffSlot; s += 2) {
 55→      lines.push(s);
 56→    }
 57→  }
 58→
 59→  return lines;
 60→}
 61→
 62→// Treble clef SVG path (simplified)
 63→function TrebleClef() {
 64→  return (
 65→    <text
 66→      x={35}
 67→      y={STAFF_LINES[4] + 10}
 68→      fontSize="72"
 69→      fill="#9ca3af"
 70→      fontFamily="serif"
 71→      style={{ userSelect: 'none' }}
 72→    >
 73→      {'\u{1D11E}'}
 74→    </text>
 75→  );
 76→}
 77→
 78→export const Staff = React.memo(function Staff({
 79→  noteIndices,
 80→  currentNoteIndex,
 81→  results,
 82→}: StaffProps) {
 83→  return (
 84→    <svg
 85→      viewBox={`0 0 ${STAFF_WIDTH} ${STAFF_HEIGHT}`}
 86→      className="w-full max-w-[600px]"
 87→      preserveAspectRatio="xMidYMid meet"
 88→    >
 89→      {/* Staff lines */}
 90→      {STAFF_LINES.map((y, i) => (
 91→        <line
 92→          key={i}
 93→          x1={20}
 94→          y1={y}
 95→          x2={STAFF_WIDTH - 20}
 96→          y2={y}
 97→          stroke="#4b5563"
 98→          strokeWidth={1}
 99→        />
100→      ))}
101→
102→      {/* Treble clef */}
103→      <TrebleClef />
104→
105→      {/* Notes */}
106→      {noteIndices.map((noteIndex, i) => {
107→        const note = ALL_NOTES[noteIndex];
108→        if (!note) return null;
109→
110→        const x = LEFT_MARGIN + i * NOTE_SPACING + NOTE_SPACING / 2;
111→        const y = staffSlotToY(note.staffSlot);
112→        const ledgerSlots = getLedgerLines(note.staffSlot);
113→        const isCurrent = i === currentNoteIndex;
114→        const result = results?.[i];
115→
116→        let color = '#9ca3af'; // default gray
117→        if (result) {
118→          color = result.correct ? '#4ade80' : '#f87171'; // green or red
119→        } else if (isCurrent) {
120→          color = '#60a5fa'; // blue highlight for current
121→        }
122→
123→        return (
124→          <g key={i}>
125→            {/* Ledger lines */}
126→            {ledgerSlots.map((slot) => {
127→              const ly = staffSlotToY(slot);
128→              return (
129→                <line
130→                  key={`ledger-${slot}`}
131→                  x1={x - 14}
132→                  y1={ly}
133→                  x2={x + 14}
134→                  y2={ly}
135→                  stroke="#4b5563"
136→                  strokeWidth={1}
137→                />
138→              );
139→            })}
140→
141→            {/* Note head */}
142→            <NoteHead
143→              x={x}
144→              y={y}
145→              isSharp={note.isSharp}
146→              color={color}
147→            />
148→          </g>
149→        );
150→      })}
151→    </svg>
152→  );
153→});
