 34→export const PianoKeyboard = React.memo(function PianoKeyboard({
 35→  onNotePlay,
 36→  activeNote,
 37→}: PianoKeyboardProps) {
 38→  const handleWhiteKey = useCallback(
 39→    (noteIndex: number) => (e: React.MouseEvent | React.TouchEvent) => {
 40→      e.preventDefault();
 41→      onNotePlay(noteIndex);
 42→    },
 43→    [onNotePlay]
 44→  );
 45→
 46→  const handleBlackKey = useCallback(
 47→    (noteIndex: number) => (e: React.MouseEvent | React.TouchEvent) => {
 48→      e.preventDefault();
 49→      e.stopPropagation();
 50→      onNotePlay(noteIndex);
 51→    },
 52→    [onNotePlay]
 53→  );
 54→
 55→  const totalWidth = WHITE_KEY_INDICES.length * WHITE_KEY_WIDTH;
 56→
 57→  // Build a map of white key index → x position
 58→  const whiteKeyPositions = new Map<number, number>();
 59→  WHITE_KEY_INDICES.forEach((noteIndex, i) => {
 60→    whiteKeyPositions.set(noteIndex, i * WHITE_KEY_WIDTH);
 61→  });
 62→
 63→  return (
 64→    <div className="relative select-none overflow-x-auto">
 65→      <div
 66→        className="relative mx-auto"
 67→        style={{ width: totalWidth, height: WHITE_KEY_HEIGHT }}
 68→      >
 69→        {/* White keys */}
 70→        {WHITE_KEY_INDICES.map((noteIndex, i) => {
 71→          const note = ALL_NOTES[noteIndex];
 72→          const x = i * WHITE_KEY_WIDTH;
 73→          const isActive = activeNote === noteIndex;
 74→
 75→          return (
 76→            <button
 77→              key={noteIndex}
 78→              onMouseDown={handleWhiteKey(noteIndex)}
 79→              onTouchStart={handleWhiteKey(noteIndex)}
