 94→                {note.keyboardKey}
 95→              </span>
 96→            </button>
 97→          );
 98→        })}
 99→
100→        {/* Black keys */}
101→        {BLACK_KEY_INFOS.map(({ noteIndex, leftWhiteIndex }) => {
102→          const leftWhiteX = whiteKeyPositions.get(leftWhiteIndex);
103→          if (leftWhiteX === undefined) return null;
104→
105→          const note = ALL_NOTES[noteIndex];
106→          const x = leftWhiteX + WHITE_KEY_WIDTH - BLACK_KEY_WIDTH / 2;
107→          const isActive = activeNote === noteIndex;
108→
109→          return (
110→            <button
111→              key={noteIndex}
112→              onMouseDown={handleBlackKey(noteIndex)}
113→              onTouchStart={handleBlackKey(noteIndex)}
114→              className="absolute rounded-b-md transition-colors duration-75 cursor-pointer"
115→              style={{
116→                left: x,
117→                top: 0,
118→                width: BLACK_KEY_WIDTH,
119→                height: BLACK_KEY_HEIGHT,
120→                backgroundColor: isActive ? '#3b82f6' : '#1f2937',
121→                zIndex: 2,
122→              }}
123→            >
124→              <span className="absolute bottom-2 left-1/2 -translate-x-1/2 text-[8px] text-gray-400 font-medium">
