 9→  const results = useSightReadingStore((s) => s.results);
10→  const targetNotes = useSightReadingStore((s) => s.targetNotes);
11→  const challengeActive = useSightReadingStore((s) => s.challengeActive);
12→  const mode = useSightReadingStore((s) => s.mode);
13→  const [visible, setVisible] = useState(false);
14→
15→  useEffect(() => {
16→    if (lastResult) {
17→      setVisible(true);
18→      const timer = setTimeout(() => setVisible(false), 800);
19→      return () => clearTimeout(timer);
20→    }
21→  }, [lastResult, results.length]);
22→
23→  // Show interval name after completing an interval challenge
24→  const showIntervalName =
25→    mode === 'interval' &&
26→    !challengeActive &&
27→    targetNotes.length === 2 &&
28→    results.length >= 2;
29→
30→  const intervalSemitones = showIntervalName
31→    ? Math.abs(
32→        ALL_NOTES[targetNotes[1]].midiNumber -
