  1→import { Difficulty, getNotesForDifficulty } from './notes';
  2→
  3→function randomFrom<T>(arr: T[]): T {
  4→  return arr[Math.floor(Math.random() * arr.length)];
  5→}
  6→
  7→/**
  8→ * Generate a single random note index for Note Drill mode.
  9→ * Avoids repeating the same note twice in a row.
 10→ */
 11→export function generateNoteDrill(
 12→  difficulty: Difficulty,
 13→  previousNote?: number
 14→): number[] {
 15→  const notes = getNotesForDifficulty(difficulty);
 16→  let note = randomFrom(notes);
 17→  // Avoid immediate repeat
 18→  while (notes.length > 1 && note.index === previousNote) {
 19→    note = randomFrom(notes);
 20→  }
 21→  return [note.index];
 22→}
 23→
 24→/**
 25→ * Generate a two-note interval challenge.
 26→ * Beginner: intervals up to a perfect 5th (7 semitones)
 27→ * Intermediate: any interval within the range
 28→ * Advanced: any interval within the range
 29→ */
 30→export function generateInterval(difficulty: Difficulty): number[] {
 31→  const notes = getNotesForDifficulty(difficulty);
 32→  const maxInterval = difficulty === 'beginner' ? 7 : 12;
 33→
 34→  const first = randomFrom(notes);
 35→  const candidates = notes.filter(
 36→    (n) =>
 37→      n.index !== first.index &&
 38→      Math.abs(n.index - first.index) <= maxInterval
 39→  );
 40→
 41→  if (candidates.length === 0) return [first.index, first.index];
 42→
 43→  const second = randomFrom(candidates);
 44→
 45→  // Always display lower note first
 46→  return first.index < second.index
 47→    ? [first.index, second.index]
 48→    : [second.index, first.index];
 49→}
 50→
 51→/**
 52→ * Generate a phrase of multiple notes.
 53→ * Length varies by difficulty: beginner=4, intermediate=4-6, advanced=6-8.
 54→ * Notes are chosen to have reasonable intervals (no huge jumps for beginners).
 55→ */
 56→export function generatePhrase(difficulty: Difficulty): number[] {
 57→  const notes = getNotesForDifficulty(difficulty);
 58→  let length: number;
 59→  let maxStep: number;
 60→
 61→  switch (difficulty) {
 62→    case 'beginner':
 63→      length = 4;
 64→      maxStep = 4; // up to major 3rd between consecutive notes
 65→      break;
 66→    case 'intermediate':
 67→      length = 4 + Math.floor(Math.random() * 3); // 4-6
 68→      maxStep = 7;
 69→      break;
 70→    case 'advanced':
 71→      length = 6 + Math.floor(Math.random() * 3); // 6-8
 72→      maxStep = 12;
 73→      break;
 74→  }
 75→
 76→  const result: number[] = [];
 77→  let current = randomFrom(notes);
 78→  result.push(current.index);
 79→
 80→  for (let i = 1; i < length; i++) {
 81→    const candidates = notes.filter(
 82→      (n) =>
 83→        n.index !== current.index &&
 84→        Math.abs(n.index - current.index) <= maxStep
 85→    );
 86→    if (candidates.length === 0) {
 87→      current = randomFrom(notes);
 88→    } else {
 89→      current = randomFrom(candidates);
 90→    }
 91→    result.push(current.index);
 92→  }
 93→
 94→  return result;
 95→}
 96→
 97→export type SightReadingMode = 'note-drill' | 'interval' | 'phrase';
 98→
 99→export function generateChallenge(
100→  mode: SightReadingMode,
101→  difficulty: Difficulty,
102→  previousNote?: number
103→): number[] {
104→  switch (mode) {
105→    case 'note-drill':
106→      return generateNoteDrill(difficulty, previousNote);
107→    case 'interval':
108→      return generateInterval(difficulty);
109→    case 'phrase':
110→      return generatePhrase(difficulty);
111→  }
112→}
