 76→  octave: def.octave,
 77→  frequency: midiToFreq(def.midi),
 78→  isSharp: def.isSharp,
 79→  midiNumber: def.midi,
 80→  staffSlot: staffSlotFromNote(def.letter, def.octave),
 81→  keyboardKey: def.key,
