 84→// Lookup: keyboard key → note index
 85→export const KEY_TO_NOTE: Record<string, number> = {};
 86→ALL_NOTES.forEach((note) => {
 87→  KEY_TO_NOTE[note.keyboardKey] = note.index;
 88→});
