 90→// Difficulty filters
 91→export type Difficulty = 'beginner' | 'intermediate' | 'advanced';
 92→
 93→export function getNotesForDifficulty(difficulty: Difficulty): NoteInfo[] {
 94→  switch (difficulty) {
 95→    case 'beginner':
 96→      // Natural notes only, C4-B4 (upper octave)
 97→      return ALL_NOTES.filter((n) => !n.isSharp && n.octave === 4);
 98→    case 'intermediate':
 99→      // All notes, full range
100→      return ALL_NOTES;
101→    case 'advanced':
102→      return ALL_NOTES;
103→  }
104→}
