 1→'use client';
 2→
 3→import { useEffect } from 'react';
 4→import { KEY_TO_NOTE } from '@/lib/sight-reading/notes';
 5→
 6→export function usePianoKeyboard(
 7→  onNotePlay: (noteIndex: number) => void,
 8→  enabled: boolean = true
 9→) {
10→  useEffect(() => {
11→    if (!enabled) return;
12→
13→    const pressedKeys = new Set<string>();
14→
15→    const handleKeyDown = (e: KeyboardEvent) => {
16→      // Ignore if typing in an input/textarea
17→      if (
18→        e.target instanceof HTMLInputElement ||
19→        e.target instanceof HTMLTextAreaElement
20→      ) {
21→        return;
22→      }
23→
24→      const key = e.key.toLowerCase();
25→
26→      // Prevent repeat (key held down)
27→      if (pressedKeys.has(key)) return;
28→
29→      const noteIndex = KEY_TO_NOTE[key];
30→      if (noteIndex !== undefined) {
31→        e.preventDefault();
32→        pressedKeys.add(key);
33→        onNotePlay(noteIndex);
34→      }
35→    };
36→
37→    const handleKeyUp = (e: KeyboardEvent) => {
38→      pressedKeys.delete(e.key.toLowerCase());
39→    };
40→
41→    window.addEventListener('keydown', handleKeyDown);
42→    window.addEventListener('keyup', handleKeyUp);
43→
44→    return () => {
45→      window.removeEventListener('keydown', handleKeyDown);
46→      window.removeEventListener('keyup', handleKeyUp);
47→    };
48→  }, [onNotePlay, enabled]);
49→}
