 78→export const Staff = React.memo(function Staff({
 79→  noteIndices,
 80→  currentNoteIndex,
 81→  results,
 82→}: StaffProps) {
 83→  return (
 84→    <svg
 85→      viewBox={`0 0 ${STAFF_WIDTH} ${STAFF_HEIGHT}`}
 86→      className="w-full max-w-[600px]"
 87→      preserveAspectRatio="xMidYMid meet"
 88→    >
 89→      {/* Staff lines */}
 90→      {STAFF_LINES.map((y, i) => (
 91→        <line
 92→          key={i}
 93→          x1={20}
 94→          y1={y}
 95→          x2={STAFF_WIDTH - 20}
 96→          y2={y}
 97→          stroke="#4b5563"
 98→          strokeWidth={1}
 99→        />
100→      ))}
101→
102→      {/* Treble clef */}
103→      <TrebleClef />
104→
105→      {/* Notes */}
106→      {noteIndices.map((noteIndex, i) => {
107→        const note = ALL_NOTES[noteIndex];
108→        if (!note) return null;
109→
110→        const x = LEFT_MARGIN + i * NOTE_SPACING + NOTE_SPACING / 2;
111→        const y = staffSlotToY(note.staffSlot);
112→        const ledgerSlots = getLedgerLines(note.staffSlot);
113→        const isCurrent = i === currentNoteIndex;
114→        const result = results?.[i];
115→
116→        let color = '#9ca3af'; // default gray
117→        if (result) {
118→          color = result.correct ? '#4ade80' : '#f87171'; // green or red
119→        } else if (isCurrent) {
120→          color = '#60a5fa'; // blue highlight for current
121→        }
122→
123→        return (
124→          <g key={i}>
125→            {/* Ledger lines */}
126→            {ledgerSlots.map((slot) => {
127→              const ly = staffSlotToY(slot);
128→              return (
129→                <line
130→                  key={`ledger-${slot}`}
131→                  x1={x - 14}
132→                  y1={ly}
133→                  x2={x + 14}
134→                  y2={ly}
135→                  stroke="#4b5563"
136→                  strokeWidth={1}
137→                />
138→              );
139→            })}
140→
141→            {/* Note head */}
142→            <NoteHead
143→              x={x}
144→              y={y}
145→              isSharp={note.isSharp}
146→              color={color}
147→            />
148→          </g>
149→        );
150→      })}
151→    </svg>
152→  );
153→});
