  3→import React, { useCallback } from 'react';
  4→import { ALL_NOTES } from '@/lib/sight-reading/notes';
  5→
  6→interface PianoKeyboardProps {
  7→  onNotePlay: (noteIndex: number) => void;
  8→  activeNote: number | null;
  9→}
 10→
 11→// White key indices in our 24-note range (C3-B4)
 12→const WHITE_KEY_INDICES = ALL_NOTES
 13→  .filter((n) => !n.isSharp)
 14→  .map((n) => n.index);
 15→
 16→// Black key info: position relative to previous white key
 17→interface BlackKeyInfo {
 18→  noteIndex: number;
 19→  leftWhiteIndex: number; // index of the white key to the left
 20→}
 21→
 22→const BLACK_KEY_INFOS: BlackKeyInfo[] = ALL_NOTES
 23→  .filter((n) => n.isSharp)
 24→  .map((n) => ({
 25→    noteIndex: n.index,
 26→    leftWhiteIndex: n.index - 1, // sharp is always 1 semitone above the natural
 27→  }));
 28→
 29→const WHITE_KEY_WIDTH = 36;
 30→const WHITE_KEY_HEIGHT = 140;
 31→const BLACK_KEY_WIDTH = 22;
 32→const BLACK_KEY_HEIGHT = 88;
 33→
 34→export const PianoKeyboard = React.memo(function PianoKeyboard({
 35→  onNotePlay,
 36→  activeNote,
 37→}: PianoKeyboardProps) {
 38→  const handleWhiteKey = useCallback(
 39→    (noteIndex: number) => (e: React.MouseEvent | React.TouchEvent) => {
 40→      e.preventDefault();
 41→      onNotePlay(noteIndex);
 42→    },
 43→    [onNotePlay]
 44→  );
 45→
 46→  const handleBlackKey = useCallback(
 47→    (noteIndex: number) => (e: React.MouseEvent | React.TouchEvent) => {
 48→      e.preventDefault();
 49→      e.stopPropagation();
 50→      onNotePlay(noteIndex);
 51→    },
 52→    [onNotePlay]
 53→  );
 54→
 55→  const totalWidth = WHITE_KEY_INDICES.length * WHITE_KEY_WIDTH;
 56→
 57→  // Build a map of white key index → x position
 58→  const whiteKeyPositions = new Map<number, number>();
 59→  WHITE_KEY_INDICES.forEach((noteIndex, i) => {
 60→    whiteKeyPositions.set(noteIndex, i * WHITE_KEY_WIDTH);
 61→  });
 62→
 63→  return (
 64→    <div className="relative select-none overflow-x-auto">
 65→      <div
 66→        className="relative mx-auto"
 67→        style={{ width: totalWidth, height: WHITE_KEY_HEIGHT }}
 68→      >
 69→        {/* White keys */}
 70→        {WHITE_KEY_INDICES.map((noteIndex, i) => {
 71→          const note = ALL_NOTES[noteIndex];
 72→          const x = i * WHITE_KEY_WIDTH;
 73→          const isActive = activeNote === noteIndex;
 74→
 75→          return (
 76→            <button
 77→              key={noteIndex}
 78→              onMouseDown={handleWhiteKey(noteIndex)}
 79→              onTouchStart={handleWhiteKey(noteIndex)}
 80→              className="absolute border border-gray-600 rounded-b-md transition-colors duration-75 cursor-pointer"
 81→              style={{
 82→                left: x,
 83→                top: 0,
 84→                width: WHITE_KEY_WIDTH - 1,
 85→                height: WHITE_KEY_HEIGHT,
 86→                backgroundColor: isActive ? '#60a5fa' : '#e5e7eb',
 87→                zIndex: 1,
 88→              }}
 89→            >
 90→              <span className="absolute bottom-2 left-1/2 -translate-x-1/2 text-[10px] text-gray-500 font-medium">
 91→                {note.name}
 92→              </span>
 93→              <span className="absolute bottom-7 left-1/2 -translate-x-1/2 text-[9px] text-gray-400 uppercase">
 94→                {note.keyboardKey}
 95→              </span>
 96→            </button>
 97→          );
 98→        })}
 99→
100→        {/* Black keys */}
101→        {BLACK_KEY_INFOS.map(({ noteIndex, leftWhiteIndex }) => {
102→          const leftWhiteX = whiteKeyPositions.get(leftWhiteIndex);
103→          if (leftWhiteX === undefined) return null;
104→
105→          const note = ALL_NOTES[noteIndex];
106→          const x = leftWhiteX + WHITE_KEY_WIDTH - BLACK_KEY_WIDTH / 2;
107→          const isActive = activeNote === noteIndex;
108→
109→          return (
110→            <button
111→              key={noteIndex}
112→              onMouseDown={handleBlackKey(noteIndex)}
113→              onTouchStart={handleBlackKey(noteIndex)}
114→              className="absolute rounded-b-md transition-colors duration-75 cursor-pointer"
115→              style={{
116→                left: x,
117→                top: 0,
118→                width: BLACK_KEY_WIDTH,
119→                height: BLACK_KEY_HEIGHT,
120→                backgroundColor: isActive ? '#3b82f6' : '#1f2937',
121→                zIndex: 2,
122→              }}
123→            >
124→              <span className="absolute bottom-2 left-1/2 -translate-x-1/2 text-[8px] text-gray-400 font-medium">
125→                {note.keyboardKey}
126→              </span>
127→            </button>
128→          );
129→        })}
130→      </div>
131→    </div>
132→  );
133→});
