17→      setVisible(true);
18→      const timer = setTimeout(() => setVisible(false), 800);
19→      return () => clearTimeout(timer);
20→    }
21→  }, [lastResult, results.length]);
22→
23→  // Show interval name after completing an interval challenge
24→  const showIntervalName =
25→    mode === 'interval' &&
26→    !challengeActive &&
27→    targetNotes.length === 2 &&
28→    results.length >= 2;
29→
30→  const intervalSemitones = showIntervalName
31→    ? Math.abs(
32→        ALL_NOTES[targetNotes[1]].midiNumber -
33→          ALL_NOTES[targetNotes[0]].midiNumber
34→      )
35→    : 0;
36→
37→  return (
38→    <div className="h-10 flex items-center justify-center gap-3">
39→      {visible && lastResult && (
40→        <span
41→          className={`
42→            text-lg font-bold animate-pulse
43→            ${lastResult === 'correct' ? 'text-green-400' : 'text-red-400'}
44→          `}
45→        >
46→          {lastResult === 'correct' ? 'Correct!' : 'Wrong'}
47→        </span>
48→      )}
49→      {showIntervalName && (
