52→        </span>
53→      )}
54→      {!challengeActive && results.length > 0 && mode === 'phrase' && (
55→        <span className="text-sm text-gray-400">
56→          {results.filter((r) => r.correct).length}/{results.length} correct
57→        </span>
58→      )}
59→    </div>
60→  );
61→}
