                </p>
                <p>
                  <span className="text-gray-400">Upper octave:</span>{' '}
                  <kbd className="bg-gray-800 px-1 rounded">Q</kbd>-
                  <kbd className="bg-gray-800 px-1 rounded">U</kbd> = C4-B4
