  1→export interface NoteInfo {
  2→  index: number;       // 0-23, position in our 2-octave range
  3→  name: string;        // e.g. "C3", "C#3"
  4→  letter: string;      // e.g. "C", "D"
  5→  octave: number;      // 3 or 4
  6→  frequency: number;   // Hz (A440 equal temperament)
  7→  isSharp: boolean;    // true for black keys
  8→  midiNumber: number;  // MIDI note number
  9→  // Staff position: number of half-steps above C3.
 10→  // For staff rendering, we map to a "staff slot" (line/space position).
 11→  // staffPosition: semitones from middle C (C4 = 12)
 12→  staffSlot: number;   // diatonic steps from C4 (middle C). C4=0, D4=1, E4=2, etc. C3=-7, D3=-6...
 13→  keyboardKey: string; // computer key mapping
 14→}
 15→
 16→// Standard A440 equal temperament frequencies
 17→// f = 440 * 2^((midi - 69) / 12)
 18→function midiToFreq(midi: number): number {
 19→  return 440 * Math.pow(2, (midi - 69) / 12);
 20→}
 21→
 22→// Map from note letter+accidental to diatonic position relative to C
 23→// C=0, D=1, E=2, F=3, G=4, A=5, B=6
 24→const diatonicMap: Record<string, number> = {
 25→  'C': 0, 'D': 1, 'E': 2, 'F': 3, 'G': 4, 'A': 5, 'B': 6,
 26→};
 27→
 28→function staffSlotFromNote(letter: string, octave: number): number {
 29→  const diatonic = diatonicMap[letter];
 30→  // C4 is our reference (staffSlot = 0)
 31→  return diatonic + (octave - 4) * 7;
 32→}
 33→
 34→interface NoteDefinition {
 35→  name: string;
 36→  letter: string;
 37→  octave: number;
 38→  midi: number;
 39→  isSharp: boolean;
 40→  key: string;
 41→}
