 72→export const ALL_NOTES: NoteInfo[] = noteDefinitions.map((def, index) => ({
 73→  index,
 74→  name: def.name,
 75→  letter: def.letter,
 76→  octave: def.octave,
 77→  frequency: midiToFreq(def.midi),
 78→  isSharp: def.isSharp,
 79→  midiNumber: def.midi,
 80→  staffSlot: staffSlotFromNote(def.letter, def.octave),
 81→  keyboardKey: def.key,
 82→}));
 83→
 84→// Lookup: keyboard key → note index
 85→export const KEY_TO_NOTE: Record<string, number> = {};
 86→ALL_NOTES.forEach((note) => {
 87→  KEY_TO_NOTE[note.keyboardKey] = note.index;
 88→});
