135→    const { selectedMelodyId } = get();
136→    if (!selectedMelodyId) return;
137→    const melody = getMelodyById(selectedMelodyId);
138→    if (!melody) return;
139→    const noteIndices = melody.notes.map((n) => n.noteIndex);
140→    set({
141→      targetNotes: noteIndices,
142→      currentNoteIndex: 0,
143→      challengeActive: true,
144→      challengeStartTime: Date.now(),
145→      results: [],
146→      lastResult: null,
147→      stats: { ...initialStats, startTime: Date.now() },
148→    });
149→  },
