151→  nextChallenge: () => {
152→    const { mode, difficulty, targetNotes, selectedMelodyId } = get();
153→    if (mode === 'melody' && selectedMelodyId) {
154→      get().startMelody();
155→      return;
156→    }
157→    const previousNote = targetNotes.length > 0 ? targetNotes[targetNotes.length - 1] : undefined;
158→    const newTargetNotes = generateChallenge(mode, difficulty, previousNote);
159→    set({
160→      targetNotes: newTargetNotes,
161→      currentNoteIndex: 0,
162→      challengeActive: true,
163→      challengeStartTime: Date.now(),
164→      lastResult: null,
165→    });
166→  },
167→
168→  submitNote: (noteIndex) => {
169→    const state = get();
170→    if (!state.challengeActive) return;
171→
172→    const targetNote = state.targetNotes[state.currentNoteIndex];
173→    if (targetNote === undefined) return;
174→
175→    const correct = noteIndex === targetNote;
176→    const responseTimeMs = state.challengeStartTime
177→      ? Date.now() - state.challengeStartTime
178→      : 0;
179→
180→    const result: NoteResult = {
181→      targetNote,
182→      playedNote: noteIndex,
183→      correct,
184→      responseTimeMs,
185→    };
186→
187→    const newResults = [...state.results, result];
188→    const newTotal = state.stats.totalAttempts + 1;
189→    const newCorrect = state.stats.correct + (correct ? 1 : 0);
190→    const newStreak = correct ? state.stats.streak + 1 : 0;
191→    const newBestStreak = Math.max(state.stats.bestStreak, newStreak);
192→
193→    let newAvgMs = state.stats.avgResponseMs;
194→    if (correct) {
195→      const prevCorrectCount = state.stats.correct;
196→      newAvgMs =
197→        prevCorrectCount === 0
198→          ? responseTimeMs
199→          : (state.stats.avgResponseMs * prevCorrectCount + responseTimeMs) /
200→            (prevCorrectCount + 1);
201→    }
202→
203→    const nextIndex = state.currentNoteIndex + 1;
204→    const challengeComplete = nextIndex >= state.targetNotes.length;
205→
206→    set({
207→      results: newResults,
208→      lastResult: correct ? 'correct' : 'wrong',
209→      currentNoteIndex: challengeComplete ? state.currentNoteIndex : nextIndex,
210→      challengeActive: !challengeComplete,
211→      challengeStartTime: challengeComplete ? null : Date.now(),
212→      stats: {
213→        ...state.stats,
214→        totalAttempts: newTotal,
215→        correct: newCorrect,
216→        streak: newStreak,
