  3→/**
  4→ * Maps a frequency (Hz) to the nearest note index in ALL_NOTES.
  5→ * Returns null if the frequency is more than 50 cents off from any note.
  6→ */
  7→export function frequencyToNoteIndex(freq: number): number | null {
  8→  if (freq <= 0) return null;
  9→
 10→  let bestIndex = -1;
 11→  let bestCents = Infinity;
 12→
 13→  for (const note of ALL_NOTES) {
 14→    const cents = Math.abs(1200 * Math.log2(freq / note.frequency));
 15→    if (cents < bestCents) {
 16→      bestCents = cents;
 17→      bestIndex = note.index;
 18→    }
 19→  }
 20→
 21→  return bestCents <= 50 ? bestIndex : null;
 22→}
