 24→/**
 25→ * Real-time pitch detection using Web Audio API + autocorrelation.
 26→ * Designed for monophonic piano note detection.
 27→ */
 28→export class PitchDetector {
 29→  private audioContext: AudioContext | null = null;
 30→  private analyser: AnalyserNode | null = null;
 31→  private stream: MediaStream | null = null;
 32→  private source: MediaStreamAudioSourceNode | null = null;
 33→  private buffer: Float32Array<ArrayBuffer> = new Float32Array(0);
 34→  private animFrameId: number | null = null;
 35→  private onPitch: ((noteIndex: number, frequency: number) => void) | null = null;
 36→  private lastNoteIndex: number | null = null;
 37→  private stableCount = 0;
 38→  private readonly STABLE_THRESHOLD = 4; // ~66ms at 60fps
 39→
 40→  async start(onPitch: (noteIndex: number, frequency: number) => void): Promise<void> {
 41→    this.onPitch = onPitch;
 42→
 43→    this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });
 44→
 45→    this.audioContext = new AudioContext();
 46→    this.source = this.audioContext.createMediaStreamSource(this.stream);
 47→
 48→    this.analyser = this.audioContext.createAnalyser();
 49→    this.analyser.fftSize = 2048;
 50→    this.buffer = new Float32Array(this.analyser.fftSize);
 51→
 52→    // Low-pass filter to improve fundamental detection
 53→    const filter = this.audioContext.createBiquadFilter();
 54→    filter.type = 'lowpass';
 55→    filter.frequency.value = 1200;
 56→
 57→    this.source.connect(filter);
 58→    filter.connect(this.analyser);
 59→
 60→    this.detect();
 61→  }
 62→
 63→  stop(): void {
 64→    if (this.animFrameId !== null) {
 65→      cancelAnimationFrame(this.animFrameId);
 66→      this.animFrameId = null;
 67→    }
 68→    if (this.source) {
 69→      this.source.disconnect();
 70→      this.source = null;
 71→    }
 72→    if (this.stream) {
 73→      this.stream.getTracks().forEach((t) => t.stop());
 74→      this.stream = null;
 75→    }
 76→    if (this.audioContext) {
 77→      this.audioContext.close();
 78→      this.audioContext = null;
 79→    }
 80→    this.analyser = null;
 81→    this.onPitch = null;
 82→    this.lastNoteIndex = null;
 83→    this.stableCount = 0;
 84→  }
 85→
 86→  private detect = (): void => {
 87→    this.animFrameId = requestAnimationFrame(this.detect);
 88→
 89→    if (!this.analyser) return;
 90→
 91→    this.analyser.getFloatTimeDomainData(this.buffer);
 92→
 93→    // RMS gate — ignore quiet signals
 94→    let rms = 0;
 95→    for (let i = 0; i < this.buffer.length; i++) {
 96→      rms += this.buffer[i] * this.buffer[i];
 97→    }
 98→    rms = Math.sqrt(rms / this.buffer.length);
 99→    if (rms < 0.01) {
100→      this.lastNoteIndex = null;
101→      this.stableCount = 0;
102→      return;
103→    }
104→
105→    const freq = this.autoCorrelate();
106→    if (freq === -1) {
107→      this.lastNoteIndex = null;
108→      this.stableCount = 0;
109→      return;
110→    }
111→
112→    const noteIndex = frequencyToNoteIndex(freq);
113→    if (noteIndex === null) {
114→      this.lastNoteIndex = null;
115→      this.stableCount = 0;
116→      return;
117→    }
118→
119→    // Debounce: require stable pitch for a few frames
120→    if (noteIndex === this.lastNoteIndex) {
121→      this.stableCount++;
122→    } else {
123→      this.lastNoteIndex = noteIndex;
124→      this.stableCount = 1;
125→    }
126→
127→    if (this.stableCount === this.STABLE_THRESHOLD && this.onPitch) {
128→      this.onPitch(noteIndex, freq);
129→    }
130→  };
131→
132→  /**
133→   * Autocorrelation pitch detection.
134→   * Returns detected frequency in Hz, or -1 if no clear pitch.
135→   */
136→  private autoCorrelate(): number {
137→    const buf = this.buffer;
138→    const sampleRate = this.audioContext?.sampleRate ?? 44100;
139→    const SIZE = buf.length;
140→
141→    // Find the first zero crossing (trim silence from ends)
142→    let r1 = 0;
143→    let r2 = SIZE - 1;
144→    const threshold = 0.2;
145→
146→    for (let i = 0; i < SIZE / 2; i++) {
147→      if (Math.abs(buf[i]) < threshold) {
148→        r1 = i;
149→        break;
150→      }
151→    }
152→    for (let i = 1; i < SIZE / 2; i++) {
153→      if (Math.abs(buf[SIZE - i]) < threshold) {
154→        r2 = SIZE - i;
155→        break;
156→      }
157→    }
158→
159→    const trimmedBuf = buf.slice(r1, r2);
160→    const trimmedSize = trimmedBuf.length;
161→
162→    if (trimmedSize < 2) return -1;
163→
164→    // Autocorrelation
165→    const c = new Float32Array(trimmedSize);
166→    for (let i = 0; i < trimmedSize; i++) {
167→      for (let j = 0; j < trimmedSize - i; j++) {
168→        c[i] += trimmedBuf[j] * trimmedBuf[j + i];
169→      }
170→    }
171→
172→    // Find first dip
173→    let d = 0;
174→    while (d < trimmedSize && c[d] > c[d + 1]) {
175→      d++;
176→    }
177→
178→    // Find peak after first dip
179→    let maxVal = -1;
180→    let maxPos = -1;
181→    for (let i = d; i < trimmedSize; i++) {
182→      if (c[i] > maxVal) {
183→        maxVal = c[i];
184→        maxPos = i;
185→      }
186→    }
187→
188→    if (maxPos === -1 || maxVal < 0.01) return -1;
189→
190→    // Parabolic interpolation for better precision
191→    const y1 = maxPos > 0 ? c[maxPos - 1] : c[maxPos];
192→    const y2 = c[maxPos];
193→    const y3 = maxPos < trimmedSize - 1 ? c[maxPos + 1] : c[maxPos];
194→    const shift = (y3 - y1) / (2 * (2 * y2 - y1 - y3));
195→    const refinedPos = maxPos + (isFinite(shift) ? shift : 0);
196→
197→    return sampleRate / refinedPos;
198→  }
199→}
