 14→  .map((n) => n.index);
 15→
 16→// Black key info: position relative to previous white key
 17→interface BlackKeyInfo {
 18→  noteIndex: number;
 19→  leftWhiteIndex: number; // index of the white key to the left
 20→}
 21→
 22→const BLACK_KEY_INFOS: BlackKeyInfo[] = ALL_NOTES
 23→  .filter((n) => n.isSharp)
 24→  .map((n) => ({
 25→    noteIndex: n.index,
 26→    leftWhiteIndex: n.index - 1, // sharp is always 1 semitone above the natural
 27→  }));
