  1→'use client';
  2→
  3→import React, { useRef, useEffect } from 'react';
  4→import { ALL_NOTES } from '@/lib/sight-reading/notes';
  5→import { NoteHead } from './NoteHead';
  6→
  7→interface StaffProps {
  8→  noteIndices: number[];
  9→  currentNoteIndex: number;
 10→  results?: { correct: boolean }[];
 11→  scrollable?: boolean;
 12→}
 13→
 14→// Staff dimensions
 15→const STAFF_HEIGHT = 260;
 16→const STAFF_TOP = 60;       // Y of top staff line
 17→const LINE_SPACING = 14;    // pixels between staff lines
 18→const LEFT_MARGIN = 80;     // space for clef
 19→const NOTE_SPACING = 70;    // horizontal spacing between notes
 20→const BASE_WIDTH = 600;
 21→
 22→// Staff line positions (5 lines, top to bottom)
 23→const STAFF_LINES = [0, 1, 2, 3, 4].map((i) => STAFF_TOP + i * LINE_SPACING);
 24→
 25→function staffSlotToY(staffSlot: number): number {
 26→  const e4Y = STAFF_LINES[4];
 27→  return e4Y - (staffSlot - 2) * (LINE_SPACING / 2);
 28→}
 29→
 30→function getLedgerLines(staffSlot: number): number[] {
 31→  const lines: number[] = [];
 32→  if (staffSlot <= 0) {
 33→    for (let s = 0; s >= staffSlot; s -= 2) {
 34→      lines.push(s);
 35→    }
 36→  }
 37→  if (staffSlot >= 12) {
 38→    for (let s = 12; s <= staffSlot; s += 2) {
 39→      lines.push(s);
 40→    }
 41→  }
 42→  return lines;
 43→}
 44→
 45→function TrebleClef() {
 46→  return (
 47→    <text
 48→      x={35}
 49→      y={STAFF_LINES[4] + 10}
 50→      fontSize="72"
 51→      fill="#9ca3af"
 52→      fontFamily="serif"
 53→      style={{ userSelect: 'none' }}
 54→    >
 55→      {'\u{1D11E}'}
 56→    </text>
 57→  );
 58→}
 59→
 60→export const Staff = React.memo(function Staff({
 61→  noteIndices,
 62→  currentNoteIndex,
 63→  results,
 64→  scrollable,
 65→}: StaffProps) {
 66→  const containerRef = useRef<HTMLDivElement>(null);
 67→  const noteRefs = useRef<(SVGGElement | null)[]>([]);
 68→
 69→  const needsScroll = scrollable && noteIndices.length > 7;
 70→  const staffWidth = needsScroll
 71→    ? LEFT_MARGIN + noteIndices.length * NOTE_SPACING + NOTE_SPACING
 72→    : BASE_WIDTH;
 73→
 74→  // Auto-scroll to current note
 75→  useEffect(() => {
 76→    if (!needsScroll || !containerRef.current) return;
 77→    const noteEl = noteRefs.current[currentNoteIndex];
 78→    if (noteEl) {
 79→      const container = containerRef.current;
 80→      const noteX = LEFT_MARGIN + currentNoteIndex * NOTE_SPACING;
 81→      const scrollTarget = noteX - container.clientWidth / 2;
 82→      container.scrollTo({ left: Math.max(0, scrollTarget), behavior: 'smooth' });
 83→    }
 84→  }, [currentNoteIndex, needsScroll]);
 85→
 86→  const svg = (
 87→    <svg
 88→      viewBox={`0 0 ${staffWidth} ${STAFF_HEIGHT}`}
 89→      className={needsScroll ? undefined : 'w-full max-w-[600px]'}
 90→      width={needsScroll ? staffWidth : undefined}
 91→      height={needsScroll ? STAFF_HEIGHT : undefined}
 92→      preserveAspectRatio="xMidYMid meet"
 93→    >
 94→      {/* Staff lines */}
 95→      {STAFF_LINES.map((y, i) => (
 96→        <line
 97→          key={i}
 98→          x1={20}
 99→          y1={y}
100→          x2={staffWidth - 20}
101→          y2={y}
102→          stroke="#4b5563"
103→          strokeWidth={1}
104→        />
105→      ))}
106→
107→      {/* Treble clef */}
108→      <TrebleClef />
109→
110→      {/* Notes */}
111→      {noteIndices.map((noteIndex, i) => {
112→        const note = ALL_NOTES[noteIndex];
113→        if (!note) return null;
114→
115→        const x = LEFT_MARGIN + i * NOTE_SPACING + NOTE_SPACING / 2;
116→        const y = staffSlotToY(note.staffSlot);
117→        const ledgerSlots = getLedgerLines(note.staffSlot);
118→        const isCurrent = i === currentNoteIndex;
119→        const result = results?.[i];
120→
121→        let color = '#9ca3af';
122→        if (result) {
123→          color = result.correct ? '#4ade80' : '#f87171';
124→        } else if (isCurrent) {
125→          color = '#60a5fa';
126→        }
127→
128→        return (
129→          <g key={i} ref={(el) => { noteRefs.current[i] = el; }}>
130→            {ledgerSlots.map((slot) => {
131→              const ly = staffSlotToY(slot);
132→              return (
133→                <line
134→                  key={`ledger-${slot}`}
135→                  x1={x - 14}
136→                  y1={ly}
137→                  x2={x + 14}
138→                  y2={ly}
139→                  stroke="#4b5563"
140→                  strokeWidth={1}
141→                />
142→              );
143→            })}
144→            <NoteHead
145→              x={x}
146→              y={y}
147→              isSharp={note.isSharp}
148→              color={color}
149→            />
150→          </g>
151→        );
152→      })}
153→    </svg>
154→  );
155→
156→  if (needsScroll) {
157→    return (
158→      <div
159→        ref={containerRef}
160→        className="w-full max-w-[600px] overflow-x-auto"
161→        style={{ scrollbarWidth: 'thin' }}
162→      >
163→        {svg}
164→      </div>
165→    );
166→  }
167→
168→  return svg;
169→});
