  1→import { Difficulty, getNotesForDifficulty } from './notes';
  2→
  3→function randomFrom<T>(arr: T[]): T {
  4→  return arr[Math.floor(Math.random() * arr.length)];
  5→}
  6→
  7→/**
  8→ * Generate a single random note index for Note Drill mode.
  9→ * Avoids repeating the same note twice in a row.
 10→ */
 11→export function generateNoteDrill(
 12→  difficulty: Difficulty,
 13→  previousNote?: number
 14→): number[] {
 15→  const notes = getNotesForDifficulty(difficulty);
 16→  let note = randomFrom(notes);
 17→  // Avoid immediate repeat
 18→  while (notes.length > 1 && note.index === previousNote) {
 19→    note = randomFrom(notes);
 20→  }
 21→  return [note.index];
 22→}
 23→
 24→/**
 25→ * Generate a two-note interval challenge.
 26→ * Beginner: intervals up to a perfect 5th (7 semitones)
 27→ * Intermediate: any interval within the range
 28→ * Advanced: any interval within the range
 29→ */
 30→export function generateInterval(difficulty: Difficulty): number[] {
 31→  const notes = getNotesForDifficulty(difficulty);
 32→  const maxInterval = difficulty === 'beginner' ? 7 : 12;
 33→
 34→  const first = randomFrom(notes);
 35→  const candidates = notes.filter(
 36→    (n) =>
 37→      n.index !== first.index &&
 38→      Math.abs(n.index - first.index) <= maxInterval
 39→  );
 40→
 41→  if (candidates.length === 0) return [first.index, first.index];
 42→
 43→  const second = randomFrom(candidates);
 44→
 45→  // Always display lower note first
 46→  return first.index < second.index
 47→    ? [first.index, second.index]
 48→    : [second.index, first.index];
 49→}
