100→  mode: SightReadingMode,
101→  difficulty: Difficulty,
102→  previousNote?: number
103→): number[] {
104→  switch (mode) {
105→    case 'note-drill':
106→    case 'note-naming':
107→      return generateNoteDrill(difficulty, previousNote);
108→    case 'interval':
109→      return generateInterval(difficulty);
110→    case 'phrase':
111→      return generatePhrase(difficulty);
112→    case 'melody':
113→      return [];
114→  }
115→}
