import { audioEngine } from './AudioEngine';

/**
 * Plucked string synthesis using layered oscillators with
 * a sharp attack and fast decay to simulate a guitar pluck.
 *
 * Uses triangle + square harmonics with quick exponential decay
 * for a brighter, more percussive attack than piano.
 */
export function playGuitarNote(
  frequency: number,
  velocity: number = 0.5
): void {
  const ctx = audioEngine.context;
  if (!ctx) return;

  const dest = audioEngine.destination;
  const time = ctx.currentTime;
  const duration = 1.2;

  // Main gain envelope — sharp attack, quick initial decay, longer sustain
  const mainGain = ctx.createGain();
  mainGain.gain.setValueAtTime(velocity * 0.4, time);
  mainGain.gain.setTargetAtTime(velocity * 0.15, time, 0.05); // quick drop
  mainGain.gain.exponentialRampToValueAtTime(0.001, time + duration);
  mainGain.connect(dest);

  // Fundamental — triangle wave for warmth
  const fundamental = ctx.createOscillator();
  fundamental.type = 'triangle';
  fundamental.frequency.setValueAtTime(frequency, time);

  const fundGain = ctx.createGain();
  fundGain.gain.setValueAtTime(1.0, time);
  fundamental.connect(fundGain).connect(mainGain);
  fundamental.start(time);
  fundamental.stop(time + duration);

  // 2nd harmonic — quiet square for brightness
  const harm2 = ctx.createOscillator();
  harm2.type = 'square';
  harm2.frequency.setValueAtTime(frequency * 2, time);

  const harm2Gain = ctx.createGain();
  harm2Gain.gain.setValueAtTime(0.08, time);
  harm2Gain.gain.exponentialRampToValueAtTime(0.001, time + 0.3);
  harm2.connect(harm2Gain).connect(mainGain);
  harm2.start(time);
  harm2.stop(time + 0.3);

  // Pluck transient — brief noise burst for pick attack
  const noiseBuffer = audioEngine.noiseBuffer;
  if (noiseBuffer) {
    const noise = ctx.createBufferSource();
    noise.buffer = noiseBuffer;

    const noiseFilter = ctx.createBiquadFilter();
    noiseFilter.type = 'bandpass';
    noiseFilter.frequency.setValueAtTime(frequency * 3, time);
    noiseFilter.Q.setValueAtTime(1, time);

    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(velocity * 0.12, time);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, time + 0.04);

    noise.connect(noiseFilter).connect(noiseGain).connect(dest);
    noise.start(time);
    noise.stop(time + 0.04);
  }
}

