// Standard tuning: low E to high E
export const STRING_NAMES = ['E', 'A', 'D', 'G', 'B', 'e'];
export const STRING_MIDI = [40, 45, 50, 55, 59, 64]; // MIDI note for open strings

const NOTE_NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

/**
 * Get the frequency of a fretted note.
 * string: 0=low E, 5=high E
 * fret: 0=open, 1-24
 */
export function fretToFrequency(string: number, fret: number): number {
  const midi = STRING_MIDI[string] + fret;
  return 440 * Math.pow(2, (midi - 69) / 12);
}

/**
 * Get the note name (e.g. "E2", "A#3") for a fretted position.
 */
export function fretToNoteName(string: number, fret: number): string {
  const midi = STRING_MIDI[string] + fret;
  const note = NOTE_NAMES[midi % 12];
  const octave = Math.floor(midi / 12) - 1;
  return `${note}${octave}`;
}

/**
 * Get just the letter name without octave (e.g. "E", "A#").
 */
export function fretToLetter(string: number, fret: number): string {
  const midi = STRING_MIDI[string] + fret;
  return NOTE_NAMES[midi % 12];
}

/**
 * Map a detected frequency to the nearest guitar fret position.
 * Returns null if the frequency is more than 50 cents off any guitar note.
 * Prefers lower strings/frets when multiple positions produce the same pitch.
 */
export function frequencyToFret(freq: number): { string: number; fret: number } | null {
  if (freq <= 0) return null;

  let bestString = -1;
  let bestFret = -1;
  let bestCents = Infinity;

  for (let s = 0; s < 6; s++) {
    for (let f = 0; f <= 15; f++) {
      const noteFreq = fretToFrequency(s, f);
      const cents = Math.abs(1200 * Math.log2(freq / noteFreq));
      if (cents < bestCents) {
        bestCents = cents;
        bestString = s;
        bestFret = f;
      }
    }
  }

  return bestCents <= 50 ? { string: bestString, fret: bestFret } : null;
}

