import { Difficulty } from '../sight-reading/notes';

export interface TabNote {
  string: number;    // 0=low E, 5=high E
  fret: number;      // 0-24
  duration: number;  // beats (1=quarter)
}

export interface ChordShape {
  name: string;
  frets: (number | null)[]; // 6 values [lowE, A, D, G, B, highE], null=muted
  barFret?: number;
}

export interface Tab {
  id: string;
  title: string;
  artist?: string;
  category: 'scale' | 'riff' | 'chord';
  difficulty: Difficulty;
  tempo: number;
  notes: TabNote[];
  chords?: ChordShape[];
}

// Helper: s=string, f=fret, d=duration (default 1 beat)
function n(s: number, f: number, d: number = 1): TabNote {
  return { string: s, fret: f, duration: d };
}

