export function getTabsByCategory(category: Tab['category']): Tab[] {
  return TABS.filter((t) => t.category === category);
}

export function getTabsByDifficulty(difficulty: Difficulty): Tab[] {
  return TABS.filter((t) => t.difficulty === difficulty);
}

export function getTabsByCategoryAndDifficulty(
  category: Tab['category'],
  difficulty: Difficulty
): Tab[] {
  return TABS.filter((t) => t.category === category && t.difficulty === difficulty);
}

export function getTabById(id: string): Tab | undefined {
  return TABS.find((t) => t.id === id);
}

