'use client';

import { STRING_NAMES } from '@/lib/guitar/notes';

interface GuitarFretboardProps {
  onNotePlayed: (string: number, fret: number) => void;
  activePosition: { string: number; fret: number } | null;
  targetPosition?: { string: number; fret: number } | null;
  maxFret?: number;
}

const FRET_MARKERS = [3, 5, 7, 9, 12, 15];
const DOUBLE_MARKER = [12];

export function GuitarFretboard({
  onNotePlayed,
  activePosition,
  targetPosition,
  maxFret = 12,
}: GuitarFretboardProps) {
  const frets = Array.from({ length: maxFret + 1 }, (_, i) => i);
  // Display strings from high e (top) to low E (bottom)
  const strings = [5, 4, 3, 2, 1, 0];

  return (
    <div className="overflow-x-auto">
      <div className="min-w-[600px]">
        {/* Fret numbers */}
        <div className="flex ml-8">
          {frets.map((f) => (
            <div
              key={f}
              className="flex-1 text-center text-[10px] text-gray-600 pb-1"
            >
              {f === 0 ? '' : f}
            </div>
          ))}
        </div>

        {/* Strings */}
        <div className="border border-gray-700 rounded-lg overflow-hidden">
          {strings.map((s) => (
            <div key={s} className="flex items-center">
              {/* String name */}
              <div className="w-8 text-center text-xs text-gray-500 font-mono shrink-0">
                {STRING_NAMES[s]}
              </div>

              {/* Frets */}
              <div className="flex flex-1">
                {frets.map((f) => {
                  const isActive =
                    activePosition?.string === s && activePosition?.fret === f;
                  const isTarget =
                    targetPosition?.string === s && targetPosition?.fret === f;

                  return (
                    <button
                      key={f}
                      onClick={() => onNotePlayed(s, f)}
                      className={`
                        flex-1 h-7 border-r border-gray-700/50 relative
                        transition-all cursor-pointer
                        ${f === 0 ? 'bg-gray-800/30' : 'bg-gray-900/50 hover:bg-gray-800/60'}
                        ${isActive ? 'bg-blue-500/30' : ''}
                        ${isTarget ? 'bg-blue-500/10' : ''}
                      `}
                    >
                      {/* String line */}
                      <div className="absolute top-1/2 left-0 right-0 h-px bg-gray-600" />

                      {/* Active dot */}
                      {isActive && (
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-4 h-4 rounded-full bg-blue-500 z-10" />
                      )}

                      {/* Target indicator */}
                      {isTarget && !isActive && (
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-4 h-4 rounded-full border-2 border-blue-400/60 z-10" />
                      )}

                      {/* Fret marker dots (only on middle of fretboard) */}
                      {s === 2 && FRET_MARKERS.includes(f) && !DOUBLE_MARKER.includes(f) && (
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-gray-700/60" />
                      )}
                      {s === 1 && DOUBLE_MARKER.includes(f) && (
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-gray-700/60" />
                      )}
                      {s === 3 && DOUBLE_MARKER.includes(f) && (
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-gray-700/60" />
                      )}

                      {/* Nut (thicker line at fret 0) */}
                      {f === 0 && (
                        <div className="absolute top-0 bottom-0 right-0 w-0.5 bg-gray-400" />
                      )}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

