'use client';

import React, { useRef, useEffect } from 'react';
import { TabNote } from '@/lib/guitar/tabs';
import { STRING_NAMES } from '@/lib/guitar/notes';

interface TabStaffProps {
  notes: TabNote[];
  currentIndex: number;
  results?: { correct: boolean }[];
  scrollable?: boolean;
}

const STAFF_HEIGHT = 160;
const STAFF_TOP = 30;
const STRING_SPACING = 20;
const LEFT_MARGIN = 50;
const NOTE_SPACING = 50;
const BASE_WIDTH = 600;

// String Y positions (high e at top, low E at bottom — standard tab convention)
const STRING_Y = Array.from({ length: 6 }, (_, i) => STAFF_TOP + i * STRING_SPACING);

export const TabStaff = React.memo(function TabStaff({
  notes,
  currentIndex,
  results,
  scrollable,
}: TabStaffProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  const needsScroll = scrollable !== false && notes.length > 9;
  const staffWidth = needsScroll
    ? LEFT_MARGIN + notes.length * NOTE_SPACING + NOTE_SPACING
    : BASE_WIDTH;

  useEffect(() => {
    if (!needsScroll || !containerRef.current) return;
    const noteX = LEFT_MARGIN + currentIndex * NOTE_SPACING;
    const container = containerRef.current;
    const scrollTarget = noteX - container.clientWidth / 2;
    container.scrollTo({ left: Math.max(0, scrollTarget), behavior: 'smooth' });
  }, [currentIndex, needsScroll]);

  const svg = (
    <svg
      viewBox={`0 0 ${staffWidth} ${STAFF_HEIGHT}`}
      className={needsScroll ? undefined : 'w-full max-w-[600px]'}
      width={needsScroll ? staffWidth : undefined}
      height={needsScroll ? STAFF_HEIGHT : undefined}
      preserveAspectRatio="xMidYMid meet"
    >
      {/* String lines */}
      {STRING_Y.map((y, i) => (
        <line
          key={i}
          x1={LEFT_MARGIN - 15}
          y1={y}
          x2={staffWidth - 15}
          y2={y}
          stroke="#4b5563"
          strokeWidth={1}
        />
      ))}

      {/* String labels — displayed as high e to low E (top to bottom) */}
      {STRING_NAMES.slice().reverse().map((name, i) => (
        <text
          key={i}
          x={18}
          y={STRING_Y[i] + 4}
          fontSize="12"
          fill="#6b7280"
          fontFamily="monospace"
          textAnchor="middle"
          style={{ userSelect: 'none' }}
        >
          {name}
        </text>
      ))}

      {/* TAB label */}
      <text
        x={5}
        y={STRING_Y[1] + 4}
        fontSize="10"
        fill="#4b5563"
        fontFamily="monospace"
        style={{ userSelect: 'none' }}
      >
        T
      </text>
      <text
        x={5}
        y={STRING_Y[2] + 4}
        fontSize="10"
        fill="#4b5563"
        fontFamily="monospace"
        style={{ userSelect: 'none' }}
      >
        A
      </text>
      <text
        x={5}
        y={STRING_Y[3] + 4}
        fontSize="10"
        fill="#4b5563"
        fontFamily="monospace"
        style={{ userSelect: 'none' }}
      >
        B
      </text>

      {/* Fret numbers */}
      {notes.map((note, i) => {
        const x = LEFT_MARGIN + i * NOTE_SPACING + NOTE_SPACING / 2;
        // String index in tab: 5=high e (top), 0=low E (bottom)
        // So string 0 (low E) maps to Y index 5, string 5 (high e) maps to Y index 0
        const yIndex = 5 - note.string;
        const y = STRING_Y[yIndex];

        const isCurrent = i === currentIndex;
        const result = results?.[i];

        let color = '#9ca3af';
        if (result) {
          color = result.correct ? '#4ade80' : '#f87171';
        } else if (isCurrent) {
          color = '#60a5fa';
        }

        return (
          <g key={i}>
            {/* Background rect to cover the line behind the number */}
            <rect
              x={x - 8}
              y={y - 9}
              width={16}
              height={18}
              fill="#1a1d27"
              rx={2}
            />
            <text
              x={x}
              y={y + 5}
              fontSize="14"
              fontWeight="bold"
              fill={color}
              fontFamily="monospace"
              textAnchor="middle"
              style={{ userSelect: 'none' }}
            >
              {note.fret}
            </text>
          </g>
        );
      })}
    </svg>
  );

  if (needsScroll) {
    return (
      <div
        ref={containerRef}
        className="w-full max-w-[600px] overflow-x-auto"
        style={{ scrollbarWidth: 'thin' }}
      >
        {svg}
      </div>
    );
  }

  return svg;
});

'use client';

import React from 'react';
import { ChordShape } from '@/lib/guitar/tabs';

interface ChordDiagramProps {
  chord: ChordShape;
  highlighted?: boolean;
}

const WIDTH = 120;
const HEIGHT = 150;
const TOP = 35;
const LEFT = 25;
const STRING_GAP = 14;
const FRET_GAP = 22;
const STRINGS = 6;
const FRETS = 5;

export const ChordDiagram = React.memo(function ChordDiagram({
  chord,
  highlighted,
}: ChordDiagramProps) {
  const borderColor = highlighted ? '#60a5fa' : '#374151';

  // Find the minimum fret (for position indicator)
  const activeFrets = chord.frets.filter((f): f is number => f !== null && f > 0);
  const minFret = activeFrets.length > 0 ? Math.min(...activeFrets) : 0;
  const maxFret = activeFrets.length > 0 ? Math.max(...activeFrets) : 0;
  const startFret = maxFret <= 5 ? 1 : minFret;
  const isOpenPosition = startFret === 1;

  return (
    <svg viewBox={`0 0 ${WIDTH} ${HEIGHT}`} className="w-24">
      {/* Chord name */}
      <text
        x={WIDTH / 2}
        y={16}
        fontSize="14"
        fontWeight="bold"
        fill="#e5e7eb"
        textAnchor="middle"
        style={{ userSelect: 'none' }}
      >
        {chord.name}
      </text>

      {/* Nut (thick line at top for open position) */}
      {isOpenPosition && (
        <line
          x1={LEFT}
          y1={TOP}
          x2={LEFT + (STRINGS - 1) * STRING_GAP}
          y2={TOP}
          stroke={borderColor}
          strokeWidth={3}
        />
      )}

      {/* Position indicator for non-open position */}
      {!isOpenPosition && (
        <text
          x={LEFT - 14}
          y={TOP + FRET_GAP / 2 + 4}
          fontSize="10"
          fill="#6b7280"
          textAnchor="middle"
          style={{ userSelect: 'none' }}
        >
          {startFret}
        </text>
      )}

      {/* Fret lines */}
      {Array.from({ length: FRETS + 1 }, (_, i) => (
        <line
          key={`fret-${i}`}
          x1={LEFT}
          y1={TOP + i * FRET_GAP}
          x2={LEFT + (STRINGS - 1) * STRING_GAP}
          y2={TOP + i * FRET_GAP}
          stroke="#4b5563"
          strokeWidth={1}
        />
      ))}

      {/* String lines */}
      {Array.from({ length: STRINGS }, (_, i) => (
        <line
          key={`string-${i}`}
          x1={LEFT + i * STRING_GAP}
          y1={TOP}
          x2={LEFT + i * STRING_GAP}
          y2={TOP + FRETS * FRET_GAP}
          stroke="#4b5563"
          strokeWidth={1}
        />
      ))}

      {/* Finger dots, muted (x), and open (o) indicators */}
      {chord.frets.map((fret, stringIdx) => {
        const x = LEFT + stringIdx * STRING_GAP;

        if (fret === null) {
          // Muted string
          return (
            <text
              key={stringIdx}
              x={x}
              y={TOP - 6}
              fontSize="10"
              fill="#9ca3af"
              textAnchor="middle"
              style={{ userSelect: 'none' }}
            >
              x
            </text>
          );
        }

        if (fret === 0) {
          // Open string
          return (
            <circle
              key={stringIdx}
              cx={x}
              cy={TOP - 10}
              r={4}
              fill="none"
              stroke="#9ca3af"
              strokeWidth={1.5}
            />
          );
        }

        // Fretted note — position relative to startFret
        const fretPos = fret - startFret + 1;
        const y = TOP + (fretPos - 0.5) * FRET_GAP;

        return (
          <circle
            key={stringIdx}
            cx={x}
            cy={y}
            r={5}
            fill="#e5e7eb"
          />
        );
      })}

      {/* Barre indicator */}
      {chord.barFret !== undefined && (
        <rect
          x={LEFT - 3}
          y={TOP + (chord.barFret - startFret + 0.5) * FRET_GAP - 4}
          width={(STRINGS - 1) * STRING_GAP + 6}
          height={8}
          rx={4}
          fill="#9ca3af"
          opacity={0.5}
        />
      )}
    </svg>
  );
});

'use client';

import { STRING_NAMES } from '@/lib/guitar/notes';

interface GuitarFretboardProps {
  onNotePlayed: (string: number, fret: number) => void;
  activePosition: { string: number; fret: number } | null;
  targetPosition?: { string: number; fret: number } | null;
  maxFret?: number;
}

const FRET_MARKERS = [3, 5, 7, 9, 12, 15];
const DOUBLE_MARKER = [12];

export function GuitarFretboard({
  onNotePlayed,
  activePosition,
  targetPosition,
  maxFret = 12,
}: GuitarFretboardProps) {
  const frets = Array.from({ length: maxFret + 1 }, (_, i) => i);
  // Display strings from high e (top) to low E (bottom)
  const strings = [5, 4, 3, 2, 1, 0];

  return (
    <div className="overflow-x-auto">
      <div className="min-w-[600px]">
        {/* Fret numbers */}
        <div className="flex ml-8">
          {frets.map((f) => (
            <div
              key={f}
              className="flex-1 text-center text-[10px] text-gray-600 pb-1"
            >
              {f === 0 ? '' : f}
            </div>
          ))}
        </div>

        {/* Strings */}
        <div className="border border-gray-700 rounded-lg overflow-hidden">
          {strings.map((s) => (
            <div key={s} className="flex items-center">
              {/* String name */}
              <div className="w-8 text-center text-xs text-gray-500 font-mono shrink-0">
                {STRING_NAMES[s]}
              </div>

              {/* Frets */}
              <div className="flex flex-1">
                {frets.map((f) => {
                  const isActive =
                    activePosition?.string === s && activePosition?.fret === f;
                  const isTarget =
                    targetPosition?.string === s && targetPosition?.fret === f;

                  return (
                    <button
                      key={f}
                      onClick={() => onNotePlayed(s, f)}
                      className={`
                        flex-1 h-7 border-r border-gray-700/50 relative
                        transition-all cursor-pointer
                        ${f === 0 ? 'bg-gray-800/30' : 'bg-gray-900/50 hover:bg-gray-800/60'}
                        ${isActive ? 'bg-blue-500/30' : ''}
                        ${isTarget ? 'bg-blue-500/10' : ''}
                      `}
                    >
                      {/* String line */}
                      <div className="absolute top-1/2 left-0 right-0 h-px bg-gray-600" />

                      {/* Active dot */}
                      {isActive && (
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-4 h-4 rounded-full bg-blue-500 z-10" />
                      )}

                      {/* Target indicator */}
                      {isTarget && !isActive && (
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-4 h-4 rounded-full border-2 border-blue-400/60 z-10" />
                      )}

                      {/* Fret marker dots (only on middle of fretboard) */}
                      {s === 2 && FRET_MARKERS.includes(f) && !DOUBLE_MARKER.includes(f) && (
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-gray-700/60" />
                      )}
                      {s === 1 && DOUBLE_MARKER.includes(f) && (
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-gray-700/60" />
                      )}
                      {s === 3 && DOUBLE_MARKER.includes(f) && (
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-gray-700/60" />
                      )}

                      {/* Nut (thicker line at fret 0) */}
                      {f === 0 && (
                        <div className="absolute top-0 bottom-0 right-0 w-0.5 bg-gray-400" />
                      )}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

