'use client';

import { useGuitarStore } from '@/lib/store/useGuitarStore';
import { getTabsByCategoryAndDifficulty, Tab } from '@/lib/guitar/tabs';
import { GuitarMode } from '@/lib/guitar/generator';

function modeToCategory(mode: GuitarMode): Tab['category'] {
  switch (mode) {
    case 'scales': return 'scale';
    case 'riffs': return 'riff';
    case 'chords': return 'chord';
  }
}

export function TabSelector() {
  const mode = useGuitarStore((s) => s.mode);
  const difficulty = useGuitarStore((s) => s.difficulty);
  const selectedTabId = useGuitarStore((s) => s.selectedTabId);
  const setSelectedTab = useGuitarStore((s) => s.setSelectedTab);
  const startSession = useGuitarStore((s) => s.startSession);

  const category = modeToCategory(mode);
  const tabs = getTabsByCategoryAndDifficulty(category, difficulty);

  if (tabs.length === 0) {
    return (
      <div className="text-center text-gray-500 py-8 text-sm">
        No {mode} for this difficulty yet.
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
      {tabs.map((tab) => {
        const isSelected = selectedTabId === tab.id;
        const noteCount = tab.chords?.length || tab.notes.length;
        const label = tab.chords ? 'chords' : 'notes';

        return (
          <button
            key={tab.id}
            onClick={() => {
              setSelectedTab(tab.id);
              // Small delay to let state update, then start
              setTimeout(() => {
                useGuitarStore.getState().startSession();
              }, 0);
            }}
            className={`text-left p-3 rounded-lg border transition-all cursor-pointer
              ${isSelected
                ? 'border-blue-500 bg-blue-500/10'
                : 'border-gray-800 bg-gray-800/30 hover:bg-gray-800/60 hover:border-gray-700'
              }`}
          >
            <div className="font-medium text-sm text-white">{tab.title}</div>
            {tab.artist && (
              <div className="text-xs text-gray-500 mt-0.5">{tab.artist}</div>
            )}
            <div className="text-xs text-gray-600 mt-1">
              {noteCount} {label} &middot; {tab.tempo} BPM
            </div>
          </button>
        );
      })}
    </div>
  );
}

