  const callbackRef = useRef(onFretDetected);
  callbackRef.current = onFretDetected;

  const handleNoteDetected = useCallback((noteIndex: number) => {
    // noteIndex is from piano's ALL_NOTES — we need the frequency
    // Instead, we intercept via the mic's detected frequency
    // This is a workaround: useMicInput gives us noteIndex, but we need frequency
    // For now, just use the noteIndex to map back to a frequency range
    void noteIndex;
  }, []);

  // We need direct frequency access, so we use useMicInput and override
  const handleFrequencyNote = useCallback((_noteIndex: number) => {
    // The useMicInput hook also exposes detectedFrequency
    // We'll read it from the return value
  }, []);

  const mic = useMicInput(handleFrequencyNote, enabled);

  // When frequency changes and we're listening, map to guitar fret
  const lastFiredRef = useRef<string | null>(null);
  const lastFiredTimeRef = useRef(0);

  // Override: use the detected frequency directly
  const wrappedStart = useCallback(async () => {
    await mic.start();
  }, [mic]);

  // Check frequency on each render when listening
  if (mic.isListening && mic.detectedFrequency) {
    const pos = frequencyToFret(mic.detectedFrequency);
    if (pos) {
      const key = `${pos.string}-${pos.fret}`;
