'use client';

import { useEffect, useRef, useState, useCallback } from 'react';
import { PitchDetector } from '../audio/PitchDetector';
import { frequencyToFret } from '../guitar/notes';

interface UseGuitarMicInputReturn {
  isListening: boolean;
  error: string | null;
  detectedFrequency: number | null;
  start: () => Promise<void>;
  stop: () => void;
}

/**
 * Mic input adapted for guitar — maps detected frequencies to string/fret positions.
 */
export function useGuitarMicInput(
  onFretDetected: (string: number, fret: number) => void,
  enabled: boolean
): UseGuitarMicInputReturn {
  const [isListening, setIsListening] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [detectedFrequency, setDetectedFrequency] = useState<number | null>(null);
  const detectorRef = useRef<PitchDetector | null>(null);
  const callbackRef = useRef(onFretDetected);
  callbackRef.current = onFretDetected;

  const lastFiredRef = useRef<string | null>(null);
  const lastFiredTimeRef = useRef(0);

  const stop = useCallback(() => {
    if (detectorRef.current) {
      detectorRef.current.stop();
      detectorRef.current = null;
    }
    setIsListening(false);
    setDetectedFrequency(null);
    lastFiredRef.current = null;
  }, []);

  const start = useCallback(async () => {
    setError(null);
    try {
      const detector = new PitchDetector();
      detectorRef.current = detector;

      await detector.start((_noteIndex, frequency) => {
        setDetectedFrequency(frequency);

        const pos = frequencyToFret(frequency);
        if (!pos) return;

        const key = `${pos.string}-${pos.fret}`;
        const now = Date.now();
        if (key === lastFiredRef.current && now - lastFiredTimeRef.current < 500) {
          return;
        }

        lastFiredRef.current = key;
        lastFiredTimeRef.current = now;
        callbackRef.current(pos.string, pos.fret);
      });

      setIsListening(true);
    } catch (err) {
      const msg =
        err instanceof DOMException && err.name === 'NotAllowedError'
          ? 'Microphone access denied'
          : 'Could not access microphone';
      setError(msg);
      setIsListening(false);
    }
  }, []);

  useEffect(() => {
    if (!enabled && isListening) {
      stop();
    }
  }, [enabled, isListening, stop]);

  useEffect(() => {
    return () => {
      if (detectorRef.current) {
        detectorRef.current.stop();
        detectorRef.current = null;
      }
    };
  }, []);

  return { isListening, error, detectedFrequency, start, stop };
}

