 14→import { MicIndicator } from '@/components/sight-reading/MicIndicator';
 15→import { useSightReadingStore } from '@/lib/store/useSightReadingStore';
 16→import { usePianoKeyboard } from '@/lib/hooks/usePianoKeyboard';
 17→import { useMicInput } from '@/lib/hooks/useMicInput';
 18→import { playPianoNote, playErrorBuzz } from '@/lib/audio/PianoSynth';
