 20→import { ALL_NOTES } from '@/lib/sight-reading/notes';
 21→import { getMelodyById } from '@/lib/sight-reading/melodies';
 22→
 23→export default function SightReadingPage() {
 24→  const mode = useSightReadingStore((s) => s.mode);
 25→  const inputMethod = useSightReadingStore((s) => s.inputMethod);
 26→  const targetNotes = useSightReadingStore((s) => s.targetNotes);
 27→  const currentNoteIndex = useSightReadingStore((s) => s.currentNoteIndex);
 28→  const challengeActive = useSightReadingStore((s) => s.challengeActive);
 29→  const selectedMelodyId = useSightReadingStore((s) => s.selectedMelodyId);
 30→  const results = useSightReadingStore((s) => s.results);
 31→  const stats = useSightReadingStore((s) => s.stats);
 32→  const startSession = useSightReadingStore((s) => s.startSession);
 33→  const nextChallenge = useSightReadingStore((s) => s.nextChallenge);
 34→  const submitNote = useSightReadingStore((s) => s.submitNote);
 35→  const submitNoteName = useSightReadingStore((s) => s.submitNoteName);
 36→  const resetSession = useSightReadingStore((s) => s.resetSession);
 37→  const setSelectedMelody = useSightReadingStore((s) => s.setSelectedMelody);
 38→
 39→  const [activeNote, setActiveNote] = useState<number | null>(null);
 40→  const activeNoteTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
 41→  const autoAdvanceTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
 42→
 43→  useEffect(() => {
 44→    return () => {
 45→      if (activeNoteTimeout.current) clearTimeout(activeNoteTimeout.current);
 46→      if (autoAdvanceTimeout.current) clearTimeout(autoAdvanceTimeout.current);
 47→    };
 48→  }, []);
 49→
 50→  const handleNotePlay = useCallback(
 51→    (noteIndex: number) => {
 52→      audioEngine.init();
 53→
 54→      setActiveNote(noteIndex);
 55→      if (activeNoteTimeout.current) clearTimeout(activeNoteTimeout.current);
 56→      activeNoteTimeout.current = setTimeout(() => setActiveNote(null), 200);
 57→
 58→      if (!challengeActive) {
 59→        playPianoNote(noteIndex);
 60→        return;
 61→      }
 62→
 63→      const state = useSightReadingStore.getState();
 64→      const targetNote = state.targetNotes[state.currentNoteIndex];
 65→      const correct = noteIndex === targetNote;
 66→
 67→      if (correct) {
 68→        playPianoNote(noteIndex);
 69→      } else {
 70→        playPianoNote(noteIndex, 0.3);
 71→        playErrorBuzz();
 72→      }
 73→
 74→      submitNote(noteIndex);
 75→
 76→      const updatedState = useSightReadingStore.getState();
 77→      if (!updatedState.challengeActive) {
 78→        if (autoAdvanceTimeout.current) clearTimeout(autoAdvanceTimeout.current);
 79→        autoAdvanceTimeout.current = setTimeout(() => {
 80→          nextChallenge();
 81→        }, 1200);
 82→      }
 83→    },
 84→    [challengeActive, submitNote, nextChallenge]
 85→  );
 86→
 87→  // Keyboard input — disabled in note-naming mode and piano-keys-only mode
 88→  const keyboardEnabled = mode !== 'note-naming' && inputMethod === 'keyboard';
 89→  usePianoKeyboard(handleNotePlay, keyboardEnabled);
 90→
 91→  // Mic input
 92→  const micEnabled = inputMethod === 'mic' && mode !== 'note-naming';
 93→  const micInput = useMicInput(handleNotePlay, micEnabled);
 94→
 95→  const handleNoteNameAnswer = useCallback(
 96→    (correct: boolean) => {
 97→      audioEngine.init();
 98→      const state = useSightReadingStore.getState();
 99→      const targetNote = state.targetNotes[state.currentNoteIndex];
100→
101→      if (correct) {
102→        playPianoNote(targetNote);
103→      } else {
104→        playErrorBuzz();
105→      }
106→
107→      const noteInfo = ALL_NOTES[targetNote];
108→      const name = noteInfo ? noteInfo.name.replace(/\d+$/, '') : '';
109→      submitNoteName(correct ? name : 'X');
110→
111→      const updatedState = useSightReadingStore.getState();
112→      if (!updatedState.challengeActive) {
113→        if (autoAdvanceTimeout.current) clearTimeout(autoAdvanceTimeout.current);
114→        autoAdvanceTimeout.current = setTimeout(() => {
115→          nextChallenge();
116→        }, 1200);
117→      }
118→    },
119→    [submitNoteName, nextChallenge]
120→  );
121→
122→  const handleStart = useCallback(() => {
123→    audioEngine.init();
124→    startSession();
125→  }, [startSession]);
126→
127→  const handleReset = useCallback(() => {
128→    if (autoAdvanceTimeout.current) clearTimeout(autoAdvanceTimeout.current);
129→    resetSession();
130→  }, [resetSession]);
131→
132→  const handleListenToMelody = useCallback(() => {
133→    if (!selectedMelodyId) return;
134→    const melody = getMelodyById(selectedMelodyId);
135→    if (!melody) return;
136→
137→    audioEngine.init();
138→    let timeOffset = 0;
139→    const beatDuration = 60 / melody.tempo;
140→
141→    for (const note of melody.notes) {
142→      const delay = timeOffset * 1000;
143→      setTimeout(() => {
144→        playPianoNote(note.noteIndex);
145→      }, delay);
146→      timeOffset += note.duration * beatDuration;
147→    }
148→  }, [selectedMelodyId]);
149→
150→  const staffResults = results.map((r) => ({ correct: r.correct }));
151→  const hasSession = stats.startTime !== null;
152→  const isMelodyMode = mode === 'melody';
153→  const isNoteNamingMode = mode === 'note-naming';
154→
155→  const modeDescriptions: Record<string, string> = {
156→    'note-drill': 'Identify notes as they appear on the staff',
157→    'note-naming': 'Type the name of the note shown on the staff',
158→    'interval': 'Play two-note intervals in order',
159→    'phrase': 'Read and play short melodies',
160→    'melody': 'Select a melody to practice',
161→  };
162→
163→  return (
164→    <div className="min-h-screen">
165→      <Header />
166→      <main className="max-w-5xl mx-auto px-4 py-6">
167→        {/* Title + selectors */}
168→        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-6">
169→          <div>
170→            <h1 className="text-xl font-bold mb-1">Sight Reading</h1>
171→            <p className="text-sm text-gray-500">
