import { create } from 'zustand';
import { Difficulty } from '../sight-reading/notes';
import { GuitarMode } from '../guitar/generator';
import { TabNote, ChordShape, getTabById } from '../guitar/tabs';

export type GuitarInputMethod = 'fretboard' | 'mic';

interface TabResult {
  target: TabNote;
  played: { string: number; fret: number };
  correct: boolean;
  responseTimeMs: number;
}

interface SessionStats {
  totalAttempts: number;
  correct: number;
  streak: number;
  bestStreak: number;
  avgResponseMs: number;
  startTime: number | null;
}

interface GuitarState {
  mode: GuitarMode;
  difficulty: Difficulty;
  inputMethod: GuitarInputMethod;
  selectedTabId: string | null;

  // Tab/scale/riff challenge
  targetNotes: TabNote[];
  currentNoteIndex: number;
  challengeActive: boolean;
  challengeStartTime: number | null;

  // Chord challenge
  targetChords: ChordShape[];
  currentChordIndex: number;

  // Results
  results: TabResult[];
  lastResult: 'correct' | 'wrong' | null;
  stats: SessionStats;

  // Actions
  setMode: (mode: GuitarMode) => void;
  setDifficulty: (difficulty: Difficulty) => void;
  setInputMethod: (method: GuitarInputMethod) => void;
  setSelectedTab: (id: string | null) => void;
  startSession: () => void;
  nextChallenge: () => void;
  submitNote: (string: number, fret: number) => void;
  advanceChord: (correct: boolean) => void;
  resetSession: () => void;
}

const initialStats: SessionStats = {
  totalAttempts: 0,
  correct: 0,
  streak: 0,
  bestStreak: 0,
  avgResponseMs: 0,
  startTime: null,
};

export const useGuitarStore = create<GuitarState>((set, get) => ({
  mode: 'riffs',
  difficulty: 'beginner',
  inputMethod: 'fretboard',
  selectedTabId: null,

  targetNotes: [],
  currentNoteIndex: 0,
  challengeActive: false,
  challengeStartTime: null,

  targetChords: [],
  currentChordIndex: 0,

  results: [],
  lastResult: null,
  stats: { ...initialStats },

  setMode: (mode) => set({
    mode,
    targetNotes: [],
    targetChords: [],
    currentNoteIndex: 0,
    currentChordIndex: 0,
    challengeActive: false,
    lastResult: null,
    selectedTabId: null,
  }),

  setDifficulty: (difficulty) => set({
    difficulty,
    targetNotes: [],
    targetChords: [],
    currentNoteIndex: 0,
    currentChordIndex: 0,
    challengeActive: false,
    lastResult: null,
    selectedTabId: null,
  }),

  setInputMethod: (inputMethod) => set({ inputMethod }),

  setSelectedTab: (id) => set({
    selectedTabId: id,
    targetNotes: [],
    targetChords: [],
    currentNoteIndex: 0,
    currentChordIndex: 0,
    challengeActive: false,
    lastResult: null,
  }),

  startSession: () => {
    const { selectedTabId } = get();
    if (!selectedTabId) return;

    const tab = getTabById(selectedTabId);
    if (!tab) return;

    if (tab.chords && tab.chords.length > 0) {
      set({
        targetChords: tab.chords,
        targetNotes: [],
        currentChordIndex: 0,
        currentNoteIndex: 0,
        challengeActive: true,
        challengeStartTime: Date.now(),
        results: [],
        lastResult: null,
        stats: { ...initialStats, startTime: Date.now() },
      });
    } else {
      set({
        targetNotes: tab.notes,
        targetChords: [],
        currentNoteIndex: 0,
        currentChordIndex: 0,
        challengeActive: true,
        challengeStartTime: Date.now(),
        results: [],
        lastResult: null,
        stats: { ...initialStats, startTime: Date.now() },
      });
    }
  },

  nextChallenge: () => {
    // Reload the same tab (retry)
    get().startSession();
  },

  submitNote: (string: number, fret: number) => {
    const state = get();
    if (!state.challengeActive || state.targetNotes.length === 0) return;

    const target = state.targetNotes[state.currentNoteIndex];
    if (!target) return;

    const correct = string === target.string && fret === target.fret;
    const responseTimeMs = state.challengeStartTime
      ? Date.now() - state.challengeStartTime
      : 0;

    const result: TabResult = {
      target,
      played: { string, fret },
      correct,
      responseTimeMs,
    };

    const newResults = [...state.results, result];
    const newTotal = state.stats.totalAttempts + 1;
    const newCorrect = state.stats.correct + (correct ? 1 : 0);
    const newStreak = correct ? state.stats.streak + 1 : 0;
    const newBestStreak = Math.max(state.stats.bestStreak, newStreak);

    let newAvgMs = state.stats.avgResponseMs;
    if (correct) {
      const prevCount = state.stats.correct;
      newAvgMs = prevCount === 0
        ? responseTimeMs
        : (state.stats.avgResponseMs * prevCount + responseTimeMs) / (prevCount + 1);
    }

    const nextIndex = state.currentNoteIndex + 1;
    const complete = nextIndex >= state.targetNotes.length;

    set({
      results: newResults,
      lastResult: correct ? 'correct' : 'wrong',
      currentNoteIndex: complete ? state.currentNoteIndex : nextIndex,
      challengeActive: !complete,
      challengeStartTime: complete ? null : Date.now(),
      stats: {
        ...state.stats,
        totalAttempts: newTotal,
        correct: newCorrect,
        streak: newStreak,
        bestStreak: newBestStreak,
        avgResponseMs: newAvgMs,
      },
    });
  },

  advanceChord: (correct: boolean) => {
    const state = get();
    if (!state.challengeActive || state.targetChords.length === 0) return;

    const newTotal = state.stats.totalAttempts + 1;
    const newCorrect = state.stats.correct + (correct ? 1 : 0);
    const newStreak = correct ? state.stats.streak + 1 : 0;
    const newBestStreak = Math.max(state.stats.bestStreak, newStreak);

    const nextIndex = state.currentChordIndex + 1;
    const complete = nextIndex >= state.targetChords.length;

    set({
      lastResult: correct ? 'correct' : 'wrong',
      currentChordIndex: complete ? state.currentChordIndex : nextIndex,
      challengeActive: !complete,
      challengeStartTime: complete ? null : Date.now(),
      stats: {
        ...state.stats,
        totalAttempts: newTotal,
        correct: newCorrect,
        streak: newStreak,
        bestStreak: newBestStreak,
      },
    });
  },

  resetSession: () => set({
    targetNotes: [],
    targetChords: [],
    currentNoteIndex: 0,
    currentChordIndex: 0,
    challengeActive: false,
    challengeStartTime: null,
    results: [],
    lastResult: null,
    stats: { ...initialStats },
  }),
}));

