'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import { Header } from '@/components/Header';
import { TabStaff } from '@/components/guitar/TabStaff';
import { ChordDiagram } from '@/components/guitar/ChordDiagram';
import { GuitarFretboard } from '@/components/guitar/GuitarFretboard';
import { GuitarModeSelector } from '@/components/guitar/GuitarModeSelector';
import { GuitarDifficultySelector } from '@/components/guitar/GuitarDifficultySelector';
import { TabSelector } from '@/components/guitar/TabSelector';
import { useGuitarStore } from '@/lib/store/useGuitarStore';
import { useGuitarMicInput } from '@/lib/hooks/useGuitarMicInput';
import { playGuitarNote } from '@/lib/audio/GuitarSynth';
import { fretToFrequency, fretToNoteName } from '@/lib/guitar/notes';
import { audioEngine } from '@/lib/audio/AudioEngine';

export default function GuitarPage() {
  const mode = useGuitarStore((s) => s.mode);
  const inputMethod = useGuitarStore((s) => s.inputMethod);
  const setInputMethod = useGuitarStore((s) => s.setInputMethod);
  const selectedTabId = useGuitarStore((s) => s.selectedTabId);
  const targetNotes = useGuitarStore((s) => s.targetNotes);
  const currentNoteIndex = useGuitarStore((s) => s.currentNoteIndex);
  const challengeActive = useGuitarStore((s) => s.challengeActive);
  const targetChords = useGuitarStore((s) => s.targetChords);
  const currentChordIndex = useGuitarStore((s) => s.currentChordIndex);
  const results = useGuitarStore((s) => s.results);
  const lastResult = useGuitarStore((s) => s.lastResult);
  const stats = useGuitarStore((s) => s.stats);
  const submitNote = useGuitarStore((s) => s.submitNote);
  const advanceChord = useGuitarStore((s) => s.advanceChord);
  const nextChallenge = useGuitarStore((s) => s.nextChallenge);
  const resetSession = useGuitarStore((s) => s.resetSession);
  const setSelectedTab = useGuitarStore((s) => s.setSelectedTab);

  const [activePosition, setActivePosition] = useState<{
    string: number;
    fret: number;
  } | null>(null);
  const activeTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (activeTimeout.current) clearTimeout(activeTimeout.current);
    };
  }, []);

  const handleFretPlay = useCallback(
    (string: number, fret: number) => {
      audioEngine.init();

      setActivePosition({ string, fret });
      if (activeTimeout.current) clearTimeout(activeTimeout.current);
      activeTimeout.current = setTimeout(() => setActivePosition(null), 200);

      const freq = fretToFrequency(string, fret);
      playGuitarNote(freq);

      if (challengeActive && targetNotes.length > 0) {
        submitNote(string, fret);
      }
    },
    [challengeActive, targetNotes.length, submitNote]
  );

  // Mic input
  const micEnabled = inputMethod === 'mic';
  const micInput = useGuitarMicInput(handleFretPlay, micEnabled);

  const isChordMode = targetChords.length > 0;
  const hasSession = selectedTabId !== null;
  const isComplete = hasSession && !challengeActive && (targetNotes.length > 0 || targetChords.length > 0);

  // Current target for fretboard highlighting
  const currentTarget =
    challengeActive && targetNotes.length > 0
      ? { string: targetNotes[currentNoteIndex].string, fret: targetNotes[currentNoteIndex].fret }
      : null;

  // Compute max fret needed for fretboard display
  const maxFretNeeded = targetNotes.reduce((max, n) => Math.max(max, n.fret), 0);
  const fretboardMax = Math.max(12, maxFretNeeded + 2);

  const accuracy =
    stats.totalAttempts > 0
      ? Math.round((stats.correct / stats.totalAttempts) * 100)
      : 0;

  return (
    <div className="min-h-screen">
      <Header />
      <main className="max-w-5xl mx-auto px-4 py-6">
        {/* Title + selectors */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-6">
          <div>
            <h1 className="text-xl font-bold mb-1">Guitar Practice</h1>
            <p className="text-sm text-gray-500">
              Scales, riffs, and chord progressions
            </p>
          </div>
          <div className="flex flex-col sm:flex-row gap-2">
            <GuitarModeSelector />
            <GuitarDifficultySelector />
          </div>
        </div>

        {/* Input method selector */}
        <div className="flex items-center gap-2 mb-4">
          <span className="text-xs text-gray-600">Input:</span>
          <div className="flex gap-1">
            {(['fretboard', 'mic'] as const).map((m) => (
              <button
                key={m}
                onClick={() => setInputMethod(m)}
                className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-all cursor-pointer
                  ${inputMethod === m
                    ? 'bg-white text-gray-900'
                    : 'bg-gray-800 text-gray-400 hover:bg-gray-700 hover:text-gray-300'
                  }`}
              >
                {m === 'fretboard' ? 'Fretboard' : 'Microphone'}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {/* Main area */}
          <div className="md:col-span-2 flex flex-col gap-4">
            {/* Tab selector (when nothing selected) */}
            {!selectedTabId && (
              <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
                <TabSelector />
              </div>
            )}

            {/* Tab display */}
            {selectedTabId && !isChordMode && (
              <div className="bg-[#1a1d27] rounded-xl p-6 border border-gray-800 flex flex-col items-center">
                {targetNotes.length > 0 ? (
                  <TabStaff
                    notes={targetNotes}
                    currentIndex={currentNoteIndex}
                    results={results.map((r) => ({ correct: r.correct }))}
                    scrollable
                  />
                ) : (
                  <div className="text-gray-500 text-sm py-8">Loading...</div>
                )}

                {/* Result feedback */}
                {lastResult && (
                  <div
                    className={`mt-3 text-sm font-medium ${
                      lastResult === 'correct' ? 'text-green-400' : 'text-red-400'
                    }`}
                  >
                    {lastResult === 'correct' ? 'Correct!' : 'Wrong'}
                  </div>
                )}

                {/* Action buttons */}
                {isComplete && (
                  <div className="flex gap-3 mt-3">
                    <button
                      onClick={nextChallenge}
                      className="px-4 py-1.5 bg-white text-gray-900 rounded-lg text-sm font-medium
                                 hover:bg-gray-200 transition-colors cursor-pointer"
                    >
                      Retry
                    </button>
                    <button
                      onClick={() => {
                        setSelectedTab(null);
                        resetSession();
                      }}
                      className="px-4 py-1.5 bg-gray-800 text-gray-300 rounded-lg text-sm font-medium
                                 hover:bg-gray-700 transition-colors cursor-pointer"
                    >
                      Back
                    </button>
                  </div>
                )}
              </div>
            )}

            {/* Chord display */}
            {selectedTabId && isChordMode && (
              <div className="bg-[#1a1d27] rounded-xl p-6 border border-gray-800 flex flex-col items-center">
                {challengeActive && targetChords[currentChordIndex] && (
                  <>
                    <div className="text-xs text-gray-500 mb-2">
                      Chord {currentChordIndex + 1} of {targetChords.length}
                    </div>
                    <ChordDiagram
                      chord={targetChords[currentChordIndex]}
                      highlighted
                    />
                    <div className="flex gap-3 mt-4">
                      <button
                        onClick={() => advanceChord(true)}
                        className="px-4 py-1.5 bg-green-600 text-white rounded-lg text-sm font-medium
                                   hover:bg-green-500 transition-colors cursor-pointer"
                      >
                        Got it
                      </button>
                      <button
                        onClick={() => advanceChord(false)}
                        className="px-4 py-1.5 bg-red-600 text-white rounded-lg text-sm font-medium
                                   hover:bg-red-500 transition-colors cursor-pointer"
                      >
                        Missed it
                      </button>
                    </div>
                  </>
                )}

                {isComplete && (
                  <div className="flex flex-col items-center gap-3">
                    <div className="text-sm text-gray-400">
                      Complete! {stats.correct}/{stats.totalAttempts} correct
                    </div>
                    <div className="flex gap-3">
                      <button
                        onClick={nextChallenge}
                        className="px-4 py-1.5 bg-white text-gray-900 rounded-lg text-sm font-medium
                                   hover:bg-gray-200 transition-colors cursor-pointer"
                      >
                        Retry
                      </button>
                      <button
                        onClick={() => {
                          setSelectedTab(null);
                          resetSession();
                        }}
                        className="px-4 py-1.5 bg-gray-800 text-gray-300 rounded-lg text-sm font-medium
                                   hover:bg-gray-700 transition-colors cursor-pointer"
                      >
                        Back
                      </button>
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Fretboard / Mic input */}
            {selectedTabId && !isChordMode && (
              <>
                {inputMethod === 'mic' && (
                  <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <button
                          onClick={micInput.isListening ? micInput.stop : micInput.start}
                          className={`w-10 h-10 rounded-full flex items-center justify-center transition-all cursor-pointer
                            ${micInput.isListening
                              ? 'bg-red-500/20 text-red-400 border border-red-500/40'
                              : 'bg-gray-800 text-gray-400 hover:bg-gray-700'
                            }`}
                        >
                          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z" />
                            <path d="M19 10v2a7 7 0 0 1-14 0v-2" />
                            <line x1="12" y1="19" x2="12" y2="23" />
                            <line x1="8" y1="23" x2="16" y2="23" />
                          </svg>
                        </button>
                        <div>
                          <div className="text-sm font-medium text-gray-300">
                            {micInput.isListening ? 'Listening...' : 'Microphone'}
                          </div>
                          {micInput.error && (
                            <div className="text-xs text-red-400">{micInput.error}</div>
                          )}
                          {!micInput.error && !micInput.isListening && (
                            <div className="text-xs text-gray-600">Click to start</div>
                          )}
                        </div>
                      </div>
                      {micInput.isListening && micInput.detectedFrequency && (
                        <div className="text-right">
                          <div className="text-lg font-bold text-white">
                            {fretToNoteName(0, Math.round(12 * Math.log2(micInput.detectedFrequency / 82.41)))}
                          </div>
                          <div className="text-xs text-gray-600">
                            {Math.round(micInput.detectedFrequency)} Hz
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {inputMethod === 'fretboard' && (
                  <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
                    <GuitarFretboard
                      onNotePlayed={handleFretPlay}
                      activePosition={activePosition}
                      targetPosition={currentTarget}
                      maxFret={fretboardMax}
                    />
                  </div>
                )}
              </>
            )}

            {/* Current target hint */}
            {challengeActive && currentTarget && (
              <div className="text-center text-xs text-gray-600">
                Target: String {currentTarget.string} Fret {currentTarget.fret}
                <span className="ml-2 text-gray-700">(shown on tab above)</span>
              </div>
            )}
          </div>

          {/* Sidebar */}
          <div className="flex flex-col gap-4">
            {/* Stats */}
            <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
              <h3 className="text-sm font-medium text-gray-400 mb-3">Stats</h3>
              <div className="space-y-2 text-sm">
                <div className="flex justify-between">
                  <span className="text-gray-500">Accuracy</span>
                  <span className="text-white font-medium">
                    {stats.totalAttempts > 0 ? `${accuracy}%` : '—'}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-500">Streak</span>
                  <span className="text-white font-medium">{stats.streak}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-500">Best Streak</span>
                  <span className="text-white font-medium">{stats.bestStreak}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-500">Correct</span>
                  <span className="text-white font-medium">
                    {stats.correct}/{stats.totalAttempts}
                  </span>
                </div>
              </div>
            </div>

            {/* Help */}
            <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
              <h3 className="text-sm font-medium text-gray-400 mb-2">How to play</h3>
              <div className="text-xs text-gray-500 space-y-1">
                {isChordMode ? (
                  <>
                    <p>View the chord diagram and try to play it on your guitar.</p>
                    <p>Click <span className="text-green-400">Got it</span> or <span className="text-red-400">Missed it</span> to self-assess.</p>
                  </>
                ) : (
                  <>
                    <p>Follow the fret numbers on the tab staff above.</p>
                    {inputMethod === 'fretboard' ? (
                      <p>Click the correct position on the fretboard below.</p>
                    ) : (
                      <p>Play the note on your guitar near the microphone.</p>
                    )}
                    <p className="text-gray-600 mt-1">
                      Numbers show fret positions. String names are on the left (high e top, low E bottom).
                    </p>
                  </>
                )}
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

