                    <div className="text-sm text-gray-400">
                      Complete! {stats.correct}/{stats.totalAttempts} correct
                    </div>
                    <div className="flex gap-3">
                      <button
                        onClick={nextChallenge}
                        className="px-4 py-1.5 bg-white text-gray-900 rounded-lg text-sm font-medium
                                   hover:bg-gray-200 transition-colors cursor-pointer"
                      >
                        Retry
                      </button>
                      <button
                        onClick={() => {
                          setSelectedTab(null);
                          resetSession();
                        }}
                        className="px-4 py-1.5 bg-gray-800 text-gray-300 rounded-lg text-sm font-medium
                                   hover:bg-gray-700 transition-colors cursor-pointer"
                      >
                        Back
                      </button>
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Fretboard / Mic input */}
            {selectedTabId && !isChordMode && (
              <>
                {inputMethod === 'mic' && (
                  <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <button
                          onClick={micInput.isListening ? micInput.stop : micInput.start}
                          className={`w-10 h-10 rounded-full flex items-center justify-center transition-all cursor-pointer
                            ${micInput.isListening
                              ? 'bg-red-500/20 text-red-400 border border-red-500/40'
                              : 'bg-gray-800 text-gray-400 hover:bg-gray-700'
                            }`}
                        >
                          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z" />
                            <path d="M19 10v2a7 7 0 0 1-14 0v-2" />
                            <line x1="12" y1="19" x2="12" y2="23" />
                            <line x1="8" y1="23" x2="16" y2="23" />
                          </svg>
                        </button>
                        <div>
                          <div className="text-sm font-medium text-gray-300">
                            {micInput.isListening ? 'Listening...' : 'Microphone'}
                          </div>
                          {micInput.error && (
                            <div className="text-xs text-red-400">{micInput.error}</div>
                          )}
                          {!micInput.error && !micInput.isListening && (
                            <div className="text-xs text-gray-600">Click to start</div>
                          )}
                        </div>
                      </div>
                      {micInput.isListening && micInput.detectedFrequency && (
                        <div className="text-right">
                          <div className="text-lg font-bold text-white">
                            {fretToNoteName(0, Math.round(12 * Math.log2(micInput.detectedFrequency / 82.41)))}
                          </div>
                          <div className="text-xs text-gray-600">
                            {Math.round(micInput.detectedFrequency)} Hz
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {inputMethod === 'fretboard' && (
                  <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
                    <GuitarFretboard
                      onNotePlayed={handleFretPlay}
                      activePosition={activePosition}
                      targetPosition={currentTarget}
                      maxFret={fretboardMax}
                    />
                  </div>
                )}
              </>
            )}

            {/* Current target hint */}
            {challengeActive && currentTarget && (
              <div className="text-center text-xs text-gray-600">
                Target: String {currentTarget.string} Fret {currentTarget.fret}
                <span className="ml-2 text-gray-700">(shown on tab above)</span>
              </div>
            )}
          </div>

          {/* Sidebar */}
          <div className="flex flex-col gap-4">
            {/* Stats */}
            <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
              <h3 className="text-sm font-medium text-gray-400 mb-3">Stats</h3>
              <div className="space-y-2 text-sm">
                <div className="flex justify-between">
                  <span className="text-gray-500">Accuracy</span>
                  <span className="text-white font-medium">
                    {stats.totalAttempts > 0 ? `${accuracy}%` : '—'}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-500">Streak</span>
                  <span className="text-white font-medium">{stats.streak}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-500">Best Streak</span>
                  <span className="text-white font-medium">{stats.bestStreak}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-500">Correct</span>
                  <span className="text-white font-medium">
                    {stats.correct}/{stats.totalAttempts}
                  </span>
                </div>
              </div>
            </div>

            {/* Help */}
            <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
              <h3 className="text-sm font-medium text-gray-400 mb-2">How to play</h3>
              <div className="text-xs text-gray-500 space-y-1">
                {isChordMode ? (
                  <>
                    <p>View the chord diagram and try to play it on your guitar.</p>
                    <p>Click <span className="text-green-400">Got it</span> or <span className="text-red-400">Missed it</span> to self-assess.</p>
                  </>
                ) : (
                  <>
                    <p>Follow the fret numbers on the tab staff above.</p>
                    {inputMethod === 'fretboard' ? (
                      <p>Click the correct position on the fretboard below.</p>
                    ) : (
                      <p>Play the note on your guitar near the microphone.</p>
                    )}
                    <p className="text-gray-600 mt-1">
                      Numbers show fret positions. String names are on the left (high e top, low E bottom).
                    </p>
                  </>
                )}
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

